INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(8325, 'koKR', 'Odzyskanie Wyspy Słońcobieżców', 'Im szybciej rozpoczniesz naukę, $N, tym lepiej dla nas wszystkich. Nie ma tu miejsca na błędy, więc słuchaj uważnie.$B$BPłonące Kryształy – zielone bryły unoszące się w powietrzu na zachód od Słonecznej Iglicy – od dawna zasilały eksperymenty prowadzone na wyspie. Strzegły ich żmije many, lecz od najazdu Plagi na Quel\'Thalas utraciliśmy nad nimi magiczną władzę i stworzenia zdziczały.$B$BNie pozostaje nam nic innego, jak przetrzebić ich szeregi i odzyskać ten teren. Zrób to, a potem wróć do mnie.', 'Zabij 8 żmijów many; znajdziesz je w pobliżu Płonących Kryształów, przy wieży i altanie.', '', 'Wróć do magistrix Erony na Wyspie Słońcobieżców w Gaju Wszechpieśni.', '', '', '', '', 0),
(8326, 'koKR', 'Przykra konieczność', 'Twój wysiłek unaocznił coś, co – szczerze mówiąc – wolałabym, żeby nie było prawdą. Nieokiełznana moc Płonących Kryształów zaburzyła naturalną równowagę wyspy na znacznie większym obszarze, niż sądziłam. Musimy teraz sięgnąć po jeszcze przykrzejsze środki, by odzyskać kontrolę.$B$BOkoliczne rysie uległy wpływowi kryształów i trzeba je uśmiercić. Przynieś mi ich obroże, $N – być może zdołam wykonać z nich magiczne okowy, które przywrócą część zwierząt do posłuszeństwa.', 'Zbierz 8 obroży rysia z zabitych rysi skoczołapów i młodych skoczołapów. Gdy skończysz, wróć do magistrix Erony na Wyspie Słońcobieżców.', '', 'Wróć do magistrix Erony na Wyspie Słońcobieżców w Gaju Wszechpieśni.', '', '', '', '', 0),
(8327, 'koKR', 'Zgłoś się do Lanthana Perilona', 'Zgłoś się do mojego asystenta, Lanthana Perilona. Przekaże ci dalsze polecenia. Podczas gdy my tu, w Słonecznej Iglicy, nadal będziemy poskramiać Płonące Kryształy, ty zajmiesz się pilniejszą sprawą dotyczącą Akademii Falthrien. Lanthan wszystko ci wyjaśni, gdy z nim porozmawiasz.$B$BIdź po prostu ścieżką na zachód, a zobaczysz go nieopodal.$B$BPowodzenia, $N – twoje dalsze sukcesy zostaną nagrodzone.', 'Porozmawiaj z Lanthanem Perilonem na Wyspie Słońcobieżców; stoi przy ścieżce prowadzącej na zachód od Słonecznej Iglicy.', '', '', '', '', '', '', 0),
(8328, 'koKR', '', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych magów na Wyspie Słońcobieżców szkoli Julia Słońcobij. Porozmawiaj z Julią i sprawdź, czego może cię nauczyć. Jej lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BJulia – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z Julią Słońcobij, nauczycielką magów, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(8329, 'koKR', '', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych wojowników na Wyspie Słońcobieżców szkoli Jesthenis Słońcobij. Porozmawiaj z Jesthenisem i sprawdź, czego może cię nauczyć. Jego lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BJesthenis – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z Jesthenisem Słońcobijem, nauczycielem wojowników, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(8330, 'koKR', 'Rzeczy Solaniana', 'W całym tym zamęcie w Słonecznej Iglicy nie miałem okazji zebrać rzeczy, które zostawiłem w różnych miejscach na wyspie. Muszę tu czuwać nad Słoneczną Studnią, więc poproszę, byś $gzebrał:zebrała; je w moim imieniu.$B$BPotrzebuję swojej wróżebnej kuli, zwoju magii Plagi i dziennika. Weź tę torbę, przyda ci się dodatkowe miejsce, bo moje rzeczy są dość nieporęczne. Przynieś mi je, a dam ci coś w podzięce – no wiesz, za fatygę. Torbę też możesz zatrzymać!', 'Zbierz wróżebną kulę, zwój magii Plagi i dziennik wartownika Studni Solaniana. Znajdziesz je na Wyspie Słońcobieżców przy stawie, przy fontannie i przy jednym z Płonących Kryształów. Gdy zbierzesz wszystkie, wróć do wartownika Studni w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', 'Wróć do wartownika Studni Solaniana w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', 0),
(8334, 'koKR', 'Agresja', 'Zanim wyślę cię do akademii, chcę, żebyś $gzajął:zajęła; się innym zadaniem, które wymaga natychmiastowej uwagi. Opiekuni – zwierzęce istoty, które niegdyś pomagały nam pielęgnować ogrody Wyspy Słońcobieżców – wymknęli się spod naszej kontroli. Pozbądź się ich bez zwłoki, ale uważaj: utrata kontroli uczyniła ich agresywnymi. To właśnie ta agresja zmusza nas do zgładzenia tych niegdyś łagodnych sług.$B$BNie sprawia mi przyjemności prosić cię o coś takiego, ale przetrwanie to przetrwanie. Opłaczę ich później.', 'Zabij 7 opiekunów i 7 dzikich opiekunów, a następnie wróć do Lanthana Perilona na Wyspie Słońcobieżców.', '', 'Wróć do Lanthana Perilona na Wyspie Słońcobieżców w Gaju Wszechpieśni.', '', '', '', '', 0),
(8335, 'koKR', 'Felendren Wygnany', 'Zdrajca naszego ludu przebywa na szczycie Akademii Falthrien, na południowym zachodzie.$B$BNazywa się Felendren i został wygnany z ziem krwawych elfów, ponieważ zlekceważył przestrogi naszych nauczycieli i starszych. To najgorszy wyrzutek naszego społeczeństwa – żyje tylko po to, by karmić swój nienasycony magiczny nałóg. Nie chciał nauczyć się panowania nad sobą; został z niego tylko cień dawnego siebie – jeden z Nędznych – i zagraża Słonecznej Iglicy.$B$BZniszcz go wraz z upiorami, które mu służą.', 'Zabij 8 tajemnych upiorów i 2 skażone tajemne upiory, a także Felendrena Wygnanego; znajdziesz ich w Akademii Falthrien. Przynieś głowę Felendrena Lanthanowi Perilonowi na Wyspie Słońcobieżców.', '', 'Wróć do Lanthana Perilona na Wyspie Słońcobieżców w Gaju Wszechpieśni.', '', '', '', '', 0),
(8336, 'koKR', 'Garść odłamków', 'Szkoda, że straciliśmy kontrolę nad tyloma stworzeniami na wyspie. Niegdyś było to spokojne miejsce nauki i badań. Teraz ledwie nadążamy z odpieraniem ataków własnych dzieł!$B$BProponuję ci magiczne dobrodziejstwo w zamian za odrobinę zbierania. Przynieś mi garść tajemnych odłamków, które mają przy sobie korzystające z many stworzenia Wyspy Słońcobieżców, a rzucę na ciebie czar, który pomoże ci w przygodach na wyspie.', 'Zbierz 6 tajemnych odłamków z dowolnych stworzeń na wyspie, które korzystają z many, a następnie wróć do arkanisty Ithanasa na Wyspie Słońcobieżców.', '', 'Wróć do arkanisty Ithanasa na Wyspie Słońcobieżców w Gaju Wszechpieśni.', '', '', '', '', 0),
(8337, 'koKR', '', '', '', '', 'Wróć do arkanisty Ithanasa w Gaju Wszechpieśni.', '', '', '', '', 0),
(8338, 'koKR', 'Skażony tajemny odłamek', 'Na zwłokach skażonego tajemnego upiora $gznalazłeś:znalazłaś; dziwny odłamek skrystalizowanej many. Różni się od innych, które $gmogłeś:mogłaś; widzieć – jest równie mroczny i złowrogi jak upiór, z którego go $gzabrałeś:zabrałaś;. Samo trzymanie go budzi w tobie nienaturalne, złe przeczucie.$B$BByć może arkanista Helion, który przebywa w altanie Słonecznej Iglicy na Wyspie Słońcobieżców, znajdzie dla niego zastosowanie.', 'Zanieś skażony tajemny odłamek arkaniście Helionowi w altanie Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(8345, 'koKR', 'Kaplica Dath\'Remara', 'Dzień po dniu stoję tutaj, czuwając i czekając. Zarzucano mi, że zbyt wiele rozmyślam o przeszłości, choć mój wzrok wciąż wypatruje horyzontu. Jestem jednak głęboko przekonany, że każdy przybysz na tej wyspie powinien oddać cześć tym, którzy poświęcili wszystko, by mógł on tu przybywać.$B$BDath\'Remar Słońcobieżca był naszym pierwszym królem. Przywiódł nas tutaj z Kalimdoru przez Wir.$B$BOdszukaj jego kaplicę na zachodzie i nie wracaj do mnie, dopóki nie przeczytasz umieszczonej na niej tablicy ku jego czci.', 'Przeczytaj tablicę w Kaplicy Dath\'Remara, a następnie wróć do wartownika Studni Solaniana w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', 'Wróć do wartownika Studni Solaniana na Wyspie Słońcobieżców w Gaju Wszechpieśni.', 'Przeczytano tablicę w Kaplicy Dath\'Remara', '', '', '', 0),
(8346, 'koKR', 'Pragnienie bez końca', 'Jeśli z pobytu na Wyspie Słońcobieżców raczysz zapamiętać tylko jedną lekcję, niech będzie nią ta: panuj nad swoim głodem magii. To pragnienie bez końca, $N – to, co wchłaniasz, musisz kontrolować i uwalniać za pomocą Tajemnego potoku. Kto zawiedzie, stanie się jednym z Nędznych... beznadziejnie uzależnionym i obłąkanym.$B$BOdszukaj żmija many i uwolnij na nim swój Tajemny potok. Naucz się panować nad swoją mocą. Gdy należycie uwolnisz Tajemny potok, wróć do mnie.', 'Użyj rasowej zdolności Tajemny potok na żmiju many, a następnie wróć do arkanisty Heliona.', '', 'Wróć do arkanisty Heliona na Wyspie Słońcobieżców w Gaju Wszechpieśni.', 'Uwolniono Tajemny potok', '', '', '', 0),
(8347, 'koKR', 'Pomoc dla zwiadowców', 'Magistrix Erona chciała, żebyś $gudał:udała; się do Srebrnej Luny i $gwsparł:wsparła; nasze starania o jej odzyskanie... oczywiście dopiero wtedy, gdy uporasz się z sytuacją w Akademii Falthrien. Nie $gzawiodłeś:zawiodłaś; nas, $N.$B$BW drodze na Plac Sokolego Skrzydła, na południe stąd, porozmawiaj ze zwiadowczynią Alarion. Znajdziesz ją niedaleko mostu.$B$BZwiadowcy zajmują się przewożeniem towarów między wyspą a lądem, a skoro $gokazałeś:okazałaś; się tak $gzaradny:zaradna;, twoja pomoc bardzo by im się przydała.', 'Porozmawiaj ze zwiadowczynią Alarion przy moście prowadzącym na południe z Wyspy Słońcobieżców.', '', '', '', '', '', '', 0),
(8350, 'koKR', 'Dokończenie dostawy', 'Śmierć kolejnego zwiadowcy to prawdziwa tragedia, ale każdy z nas bierze to ryzyko na siebie, przyjmując tę pracę. Magistrix Erona ze Słonecznej Iglicy musi dostarczyć tę paczkę do karczmy na Placu Sokolego Skrzydła, i to jak najszybciej.$B$BBrakuje nam rąk do pracy i nie mam nikogo, kto mógłby nas zastąpić.$B$BNie będę cię okłamywać: droga na Plac Sokolego Skrzydła bywa niezwykle niebezpieczna, jeśli zejdziesz z bezpiecznej Alei Świtu. Czujesz się na siłach, $N?', 'Dostarcz paczkę Erony karczmarce Delaniel w karczmie na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(8463, 'koKR', 'Niestabilne kryształy many', 'Banda Nędznych złupiła niedawno zapas niestabilnych kryształów many z jednego z naszych tajemnych sanktuariów. Jeśli nie obchodzić się z nimi właściwie, kryształy mogą wybuchnąć z siłą zdolną wyrwać dziurę w murach miasta.$B$BWiesz, $N, niespecjalnie mnie obchodzi, czy wysadzą się w powietrze, czerpiąc z niestabilnych tajemnych źródeł, ale cała ta sprawa źle świadczy o moich ludziach.$B$BPrzynieś mi wszystkie skradzione kryształy, jakie znajdziesz; mogą wciąż leżeć w swoich skrzyniach.', 'Przynieś 6 niestabilnych kryształów many Aeldonowi Słonecznemu Piętnu na Placu Sokolego Skrzydła.', '', 'Wróć do Aeldona Słonecznego Piętna na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', '', '', '', 0),
(8468, 'koKR', 'Poszukiwany: Thaelis Łaknący', 'Miasto Srebrna Luna wyznacza niniejszym nagrodę za głowę Thaelisa Łaknącego, osławionego przywódcy Nędznych. Jest on poszukiwany za liczne zbrodnie przeciwko mieszkańcom Srebrnej Luny, w tym za zabójstwo dwóch strażników miejskich.$B$BPo odbiór nagrody należy zgłosić się do sierżanta Kan\'rena.', 'Przynieś głowę Thaelisa sierżantowi Kan\'renowi na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', 'Wróć do sierżanta Kan\'rena na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', '', '', '', 0),
(8472, 'koKR', 'Poważna awaria', 'Tajemne patrolowce, stworzone przez naszych przodków do ochrony miasta, popadły w niebezpieczną ruinę. Nie rozpoznają w nas swoich panów i atakują, gdy tylko nas zobaczą!$B$BChoć zbudowano je przed wieloma laty, zasilające je tajemne rdzenie wciąż są dla nas bardzo przydatne i cenne. Zbierz te rdzenie i przynieś mi je, a znów zrobię z nich dobry użytek. Patrolowce znajdziesz w zrujnowanej części Srebrnej Luny, na północnym zachodzie.', 'Zbierz 6 tajemnych rdzeni z tajemnych patrolowców krążących po ruinach Srebrnej Luny i przynieś je magistrowi Jaronisowi na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', 'Wróć do magistra Jaronisa na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', '', '', '', 0),
(8473, 'koKR', 'Ponure zadanie', 'Nastały dla nas trudne czasy, $N. Decyzja o spaleniu lasów na granicy z Widmowymi Ziemiami, by powstrzymać pochód Plagi, przyszła nam z wielkim trudem.$B$BDrzewce, od lat nasi przyjaciele, próbują teraz odrodzić las w Spalonym Gaju.$B$BTo bolesna prośba, $N, ale nie zdołaliśmy przekonać naszych dawnych sojuszników, by zaniechali swoich starań. Musisz ich powstrzymać jedynym sposobem, jaki nam pozostał: siłą.', 'Zabij 10 uschniętych zielonych strażników w Spalonym Gaju. Następnie złóż raport Lariannie Rzecznowiew w wieży na północny zachód od Spalonego Gaju w Gaju Wszechpieśni.', '', 'Wróć do Larianny Rzecznowiew na Przełęczy Złotego Konaru w Gaju Wszechpieśni.', '', '', '', '', 0),
(8474, 'koKR', 'Wisior Starej Białej Kory', 'Na wisiorze wyryto inicjały L.R. Być może te litery doprowadzą cię do jego twórcy.', 'Odnajdź osobę, która mogła wykonać wisior Starej Białej Kory. Może powiedzieć ci o nim coś więcej.', '', '', '', '', '', '', 0),
(8475, 'koKR', 'Trupia Blizna', 'Czarny pas ziemi przecinający Gaj Wszechpieśni to wieczna pamiątka dnia, w którym Arthas poprowadził Plagę do naszego ukochanego miasta.$B$BTa skaza to coś więcej niż szpetny widok – do dziś ściąga do Srebrnej Luny Plagę z Widmowych Ziem.$B$BIdź, $N, i pomóż moim ludziom wybijać bezmyślnych nieumarłych, którzy wędrują Trupią Blizną.', 'Zabij 8 plagokostnych łupieżców i złóż raport tropicielce Jaeli na Trupiej Bliźnie w Gaju Wszechpieśni.', '', 'Wróć do tropicielki Jaeli na Trupiej Bliźnie w Gaju Wszechpieśni.', '', '', '', '', 0),
(8476, 'koKR', 'Wtargnięcie Amanów', 'Nie władamy rozległymi królestwami jak ludzie czy orkowie. Niemal wszystko, co zostało nam z naszych ziem w Azeroth, masz przed oczami, $N.$B$BDopóki nie dotrzemy do Rubieży, musimy za wszelką cenę bronić tego skrawka ziemi, który nam pozostał.$B$BAmanowie – trolle, nasi niecywilizowani sąsiedzi z południowego wschodu – mają rzecz jasna odmienne zdanie co do tego, do kogo należą te ziemie. Nie możemy dłużej tolerować ich codziennych napaści. Udaj się do ich osad, Zeb\'Watha i Tor\'Watha, i daj im nauczkę.', 'Porucznik Świtobieżna z Ustronia Obieżyświatów w Gaju Wszechpieśni chce, żebyś $gzabił:zabiła; 5 berserkerów Amanów i 5 miotaczy toporów Amanów.', '', 'Wróć do porucznik Świtobieżnej w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', 0),
(8477, 'koKR', 'Młot kowala włóczni', 'Amanowie i sin\'dorei od dawna darzą się wzajemną niechęcią i otwartą wrogością. Nie przeszkadza mi to jednak doceniać dzieła innego rzemieślnika, $N.$B$BW moje ręce trafiło kilka sztuk broni Amanów i muszę przyznać, że jakość ich wykonania zrobiła na mnie wrażenie. Podobno kowal włóczni Otembe posługuje się magicznym młotem tak lekkim i wyważonym, że pozwala mu pracować z wielką zręcznością i sprawnością.$B$BJeśli przyniesiesz mi to narzędzie, wykuję nim dla ciebie broń.', 'Odszukaj w Tor\'Watha, na południowy wschód od Ustronia Obieżyświatów, kowala włóczni Otembego i przynieś młot Otembego Arathel Słonecznej Kuźni w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', 'Wróć do Arathel Słonecznej Kuźni w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', 0),
(8478, 'koKR', 'Wybierz broń', '', '', '', '', '', '', '', '', 0),
(8479, 'koKR', 'Zul\'Marosh', 'Podejdź bliżej, mon. Nie bój się, Ven\'jashi nie zrobić ci krzywdy.$B$BMy, trolle Mrocznej Włóczni, być śmiertelnymi wrogami Amanów, tak jak wy. Ich szef Zul\'Marosh to zły troll. On dać mi złą truciznę i zostawić mnie w tej klatce, żebym zdechnąć.$B$BJa się nie bać śmierci, mon. Ja patrzeć śmierci w oczy i śmiać się jej w twarz.$B$BAle ja jeszcze nie móc umrzeć w spokoju, mon. Nie póki Zul\'Marosh nie być martwy. Ty go znaleźć za jeziorem, w Zeb\'Watha. Ja wstrzymywać tę truciznę, aż ty przynieść mi jego wielki brzydki łeb, mon. Dopiero wtedy ja umrzeć w spokoju.', 'Ven\'jashi, trollowy więzień w Tor\'Watha, chce, żebyś $gprzyniósł:przyniosła; mu głowę wodza Zul\'Marosha. Wódz Zul\'Marosh przebywa w Zeb\'Watha, po drugiej stronie Jeziora Elrendar.', '', 'Wróć do Ven\'jashiego w Tor\'Watha w Gaju Wszechpieśni.', '', '', '', '', 0),
(8480, 'koKR', 'Utracone uzbrojenie', 'Nędzni z każdym dniem stają się coraz zuchwalsi, $N. Zorganizowali się na tyle, by napaść na Przystań Słonecznego Żagla.$B$BJakby tego wstydu było mało, podczas ataku zostawiliśmy tam większość broni. Przynieś mi nasze uzbrojenie, byśmy mogli pokazać tym łotrom, kto tu rządzi.', 'Przynieś 8 sztuk uzbrojenia sin\'dorei Velendrisowi Białemu Porankowi w Gaju Wszechpieśni.', '', 'Wróć do Velendrisa Białego Poranka w Gaju Wszechpieśni.', '', '', '', '', 0),
(8482, 'koKR', 'Obciążające dokumenty', 'Dokumenty zawierają szczegółowe mapy różnych strategicznych budowli w Gaju Wszechpieśni. Jest wśród nich także dokładny szkic tajemnego sanktuarium. Widnieją na nich liczne notatki w języku, którego nie rozpoznajesz.$B$BSkoro miał je przy sobie darnasyjski szpieg, dobrze byłoby zanieść je kapitanowi straży – Aeldonowi Słonecznemu Piętnu.', 'Zanieś obciążające dokumenty Aeldonowi Słonecznemu Piętnu na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(8483, 'koKR', 'Krasnoludzki szpieg', 'Posłuchaj, $N. To bardzo delikatna sprawa; choć wiemy już, kim jest szpieg, nie możemy zabić go przy świadkach. Nie możemy też próbować go pojmać, bo ryzyko ucieczki jest zbyt duże.$B$BOdszukaj poszukiwacza Kowadłostroża przy Północnym Sanktuarium i zabij go. Zrób to po cichu – nikt nie może się dowiedzieć, że wpuściliśmy szpiega do naszego miasta.$B$BPrzynieś mi jego głowę jako dowód. Żelazna Kuźnia się nauczy, że z sin\'dorei się nie zadziera.', 'Przynieś głowę poszukiwacza Kowadłostroża Aeldonowi Słonecznemu Piętnu na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', 'Wróć do Aeldona Słonecznego Piętna na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', '', '', '', '', 0),
(8486, 'koKR', 'Tajemna niestabilność', 'Najwyższy czas, żeby ten tępak Caidanis kogoś tu przysłał.$B$BOstrzegałam przed niebezpieczeństwem zwiększania obciążenia Zachodniego Sanktuarium! Teraz jeden z naszych przetworników energii jest zniszczony, a z sanktuarium wylewają się tajemne upiory!$B$BMusisz rozprawić się z tymi stworami, zanim wyślemy kogokolwiek do naprawy. Pospiesz się!', 'Opiekunka linii mocy Velania chce, żebyś $gzabił:zabiła; 5 upiorów many i 5 łowców many.', '', 'Wróć do opiekunki linii mocy Velanii w Zachodnim Sanktuarium w Gaju Wszechpieśni.', '', '', '', '', 0),
(8487, 'koKR', 'Skażona gleba', 'To było w pełni sprawne tajemne sanktuarium, zanim Arthas i jego armia Plagi przeorali je w drodze do Srebrnej Luny.$B$BTeraz jest dla nas równie bezużyteczne jak każdy skrawek Trupiej Blizny. Gleba jest skażona, przyciąga nieumarłych, a przepływ energii w liniach mocy został całkowicie zaburzony.$B$BChcę się dowiedzieć, $N, czy to skażenie da się odwrócić. Zbierz próbki gleby z tej okolicy, żebym mogła je zbadać. Być może z czasem zdołamy przywrócić tu dawny porządek.', 'Uczennica Mirveda we Wschodnim Sanktuarium w Gaju Wszechpieśni chce, żebyś $gzebrał:zebrała; 8 skażonych próbek gleby.', '', 'Wróć do uczennicy Mirvedy we Wschodnim Sanktuarium w Gaju Wszechpieśni.', '', '', '', '', 0),
(8488, 'koKR', 'Nieoczekiwane wyniki', 'Coś jest nie tak, $N. Wyczuwam obecność Plagi. Bądź $ggotów:gotowa; do walki!', 'Chroń uczennicę Mirvedę przed zasadzką Plagi.', 'Chroń uczennicę Mirvedę', 'Wróć do uczennicy Mirvedy we Wschodnim Sanktuarium w Gaju Wszechpieśni.', '', '', '', '', 0),
(8489, 'koKR', 'Nienaruszony przetwornik', 'Ten przedmiot wygląda na jeden z tajemnych przetworników, o których wspominała opiekunka linii mocy Velania. Ogień go nie uszkodził, może więc znajdzie dla niego zastosowanie.', 'Zanieś nienaruszony tajemny przetwornik opiekunce linii mocy Velanii.', '', '', '', '', '', '', 0),
(8490, 'koKR', 'Zasilanie naszej obrony', 'Pradawne kamienie runiczne zasilały niegdyś barierę ochronną wzdłuż granicy Gaju Wszechpieśni. Wiele z nich zniszczono podczas ataku Arthasa, inne skradziono.$B$BZ trzech, które pozostały, tylko ten zachował moc. Kamień runiczny na wschodzie da się jednak może uratować.$B$BWeź ten kryształ i przelej jego energię we Wschodni Kamień Runiczny. Nie powinno to potrwać dłużej niż minutę. Uważaj jednak – przyciągnie to okoliczne sługi Plagi, które zechcą go zniszczyć. Nie pozwól im na to!', 'Umieść nasycony kryształ przy Wschodnim Kamieniu Runicznym i broń go przed Plagą przez 1 minutę. Oddaj nasycony kryształ strażnikowi run Deryanowi w Gaju Wszechpieśni, by otrzymać nagrodę.', '', 'Wróć do strażnika run Deryana przy Kamieniu Runicznym Falithas w Gaju Wszechpieśni.', 'Kamień runiczny zasilony', '', '', '', 0),
(8491, 'koKR', 'Zbieranie skór', 'Skoczołapy zamieszkujące tę okolicę słyną ze skór najwyższej jakości. Widzieliśmy nawet, jak ta nocnoelfia hołota przybywa na nasze ziemie tylko po to, by na nie kłusować.$B$BPotyczki z Amanami nadwyrężyły nasze zapasy ekwipunku, a tropiciele nie mają już czasu polować na skóry. Jeśli zechcesz pomóc i zebrać skóry skoczołapów, chętnie nagrodzę cię ręcznie wykonaną częścią pancerza. Czatujące skoczołapy znajdziesz w całym lesie na północ stąd.', 'Velan Jasnodąb z Wioski Rześkiej Bryzy w Gaju Wszechpieśni chce, żebyś $gprzyniósł:przyniosła; mu 6 skór skoczołapa.', '', 'Wróć do Velana Jasnodęba w Wiosce Rześkiej Bryzy w Gaju Wszechpieśni.', '', '', '', '', 0),
(8547, 'koKR', '', 'Witaj w World of Warcraft!$B$BW podziękowaniu za zakup Edycji kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Marsilli Gwieździe Zarannej na Placu Sokolego Skrzydła. W zamian otrzymasz prezent: małego towarzysza, który będzie ci towarzyszył w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy udanego pobytu w świecie World of Warcraft!', 'Zanieś bon podarunkowy z Placu Sokolego Skrzydła Marsilli Gwieździe Zarannej na Placu Sokolego Skrzydła.', '', '', '', '', '', '', 0),
(8563, 'koKR', 'Szkolenie czarnoksiężnika', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych czarnoksiężników na Wyspie Słońcobieżców szkoli przywoływacz Teli\'Larien. Porozmawiaj z przywoływaczem Teli\'Larienem i sprawdź, czego może cię nauczyć. Jego lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BTwój nauczyciel – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z przywoływaczem Teli\'Larienem, nauczycielem czarnoksiężników, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(8564, 'koKR', '', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych kapłanów na Wyspie Słońcobieżców szkoli matrona Arena. Porozmawiaj z matroną i sprawdź, czego może cię nauczyć. Jej lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BMatrona Arena – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z matroną Areną, nauczycielką kapłanów, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(8884, 'koKR', 'Rybie łby, rybie łby...', 'Witaj, $N. Spójrz w stronę brzegu; co widzisz? Właśnie tak – naszą plażę... nasz Spokojny Brzeg opanowała zaraza zwana murlokami.$B$BNie ścierpię tego!$B$BMam dla ciebie zadanie. Jeśli czujesz się na siłach, chcę ich łbów! Przetrzebmy ich tak mocno, że jeśli mają choć odrobinę rozumu, wrócą do mętnych głębin, z których wypełzły!', 'Zbierz 8 głów murloków Ponurej Łuski. Zanieś je Hathvelionowi Słońcowzrokowi w Gaju Wszechpieśni, na urwisku z widokiem na Spokojny Brzeg.', '', 'Wróć do Hathveliona Słońcowzroka w Gaju Wszechpieśni.', '', '', '', '', 0),
(8885, 'koKR', 'Pierścień Mmmrrrggglll', 'Murloki Ponurej Łuski nie przestraszyły się twoich wysiłków. Myślę jednak, że wiem, co je przepędzi, a przy okazji pozwoli mi się osobiście zemścić.$B$BMają wodza, który każe się nazywać Mmmrrrggglll. Krąży po Złotym Wybrzeżu na południe od ujścia rzeki. Ta bestia zabiła niegdyś mojego towarzysza, a teraz nosi jego pierścień, otwarcie z nas szydząc.$B$BZabij Mmmrrrggglll i odzyskaj pierścień mojego przyjaciela. Wtedy zobaczymy, jak te potwory podkulą ogony!', 'Odbierz pierścień Mmmrrrggglll z martwych łap wodza Ponurej Łuski. Zanieś go Hathvelionowi Słońcowzrokowi w Gaju Wszechpieśni, na urwisku z widokiem na Spokojny Brzeg.', '', 'Wróć do Hathveliona Słońcowzroka w Gaju Wszechpieśni.', '', '', '', '', 0),
(8886, 'koKR', 'Piraci Ponurej Łuski!', 'Dzięki niebiosom, że jesteś, $N! Te oślizłe murloki Ponurej Łuski porwały mój ładunek niczym piraci! Dość, że Nędzni ukradli tę odrobinę magicznych towarów, jaką miałam, to jeszcze murloki zabrały resztę! Do czego ten kraj doszedł?$B$BCzy $gmógłbyś:mogłabyś; odzyskać mój ładunek? Nie oczekuję, że zdołasz odzyskać wszystko, ale w tej chwili będę wdzięczna za każdą część. Na pewno zrobiły to murloki Ponurej Łuski z chat na zachód i południe od przystani na Złotym Wybrzeżu, jestem tego pewna!$B', 'Odzyskaj 6 sztuk ładunku kapitan Kelisendry i zanieś je kapitan Kelisendrze do strzeżonego obozu tuż na wschód od Przystani Słonecznego Żagla w Gaju Wszechpieśni.', '', 'Wróć do kapitan Kelisendry w Gaju Wszechpieśni.', '', '', '', '', 0),
(8887, 'koKR', 'Zaginione locje kapitan Kelisendry', 'Ciekawe... to, co $gznalazłeś:znalazłaś;, to nieprzemakalny skórzany tubus z kilkoma arkuszami pergaminu. Sądząc po oznaczeniach, są to locje nawigacyjne, a na każdej widnieje podpis niejakiej kapitan Kelisendry.$B$B$GSłyszałeś:Słyszałaś; o niewielkim, strzeżonym obozie tuż na wschód od pobliskiej Przystani Słonecznego Żagla. Może tam znajdziesz panią kapitan?', 'Zwróć zaginione locje kapitan Kelisendry ich właścicielce w strzeżonym obozie tuż na wschód od Przystani Słonecznego Żagla w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(8888, 'koKR', 'Uczennica magistra', '$N, wysłuchaj mojej prośby. Z powodów, o których nie mogę teraz mówić, postanowiłem zamknąć moją pobliską szkołę. Kilka dni temu posłałem tam z tym właśnie zadaniem jedną z moich uczennic, Loralthalis. Od tamtej pory nie mam od niej wieści.$B$BCzy udasz się do Iglicy Krańca Mroku i sprawdzisz, czy nic jej nie jest? Trafisz tam, idąc ścieżką na północ od Ustronia Obieżyświatów, a gdy droga się rozwidli, skręć w prawo.', 'Porozmawiaj z uczennicą Loralthalis w pobliżu Iglicy Krańca Mroku w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(8889, 'koKR', 'Wyłączenie Iglicy', 'Jak być może wiesz, magister Kraniec Mroku odesłał mnie tu, bym wyłączyła źródła mocy zasilające Iglicę. Są trzy, każde w innym miejscu wewnątrz.$B$BNiestety, chyba przybyłam za późno – Iglicę Krańca Mroku opanowały dziwne, magiczne stworzenia. Sama nie mam dość wprawy, by temu podołać, ale ktoś taki jak ty z pewnością zrobi to bez trudu, prawda?', 'Wyłącz 3 źródła mocy Iglicy Krańca Mroku wewnątrz Iglicy Krańca Mroku. Następnie zwróć klejnot dezaktywujący uczennicy Loralthalis w Gaju Wszechpieśni.', '', 'Wróć do uczennicy Loralthalis w Gaju Wszechpieśni.', 'Pierwsze źródło mocy wyłączone', 'Drugie źródło mocy wyłączone', 'Trzecie źródło mocy wyłączone', '', 0),
(8890, 'koKR', 'Wieści z Iglicy', '$N, mam do ciebie ostatnią prośbę. Czy zechcesz przekazać magistrowi Krańcowi Mroku, który przebywa w Ustroniu Obieżyświatów, co się tu wydarzyło? Powiedz mu, że nic mi nie jest, ale koniecznie daj mu znać, że niektórzy z uczniów stali się Nędznymi.$B$BDziękuję za pomoc!', 'Wróć do magistra Krańca Mroku w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(8891, 'koKR', 'Porzucone badania', '$GZnalazłeś:Znalazłaś; coś, co wygląda na dziennik badań pozostawiony przez magistra Kraniec Mroku. Pobieżna lektura ujawnia wstrząsające próby filtrowania skażonych przepływów magii, które mogą tłumaczyć, co wydarzyło się w Iglicy Krańca Mroku. Magister z pewnością zechce go odzyskać.', 'Zwróć dziennik magistra Krańca Mroku jego właścicielowi w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(8892, 'koKR', 'Sytuacja w Przystani Słonecznego Żagla', 'Przystań Słonecznego Żagla opanowała hołota Nędznych. Gdy tylko ściągniemy tam posiłki, pokażemy tym zbirom, kto tu rządzi, $N.$B$BTymczasem możesz pomóc, ucząc ich odrobiny dyscypliny. Idź tam i pokaż im, że z nami się nie zadziera. Przystań Słonecznego Żagla znajdziesz tuż na zachód od Wioski Rześkiej Bryzy.', 'Zabij 5 nędznych zbirów i 5 nędznych chuliganów, a następnie złóż raport tropicielowi Degolienowi w Gaju Wszechpieśni.', '', 'Wróć do tropiciela Degoliena w Gaju Wszechpieśni.', '', '', '', '', 0),
(8894, 'koKR', 'Porządki na terenie', 'Mówię ci, to okropne! W iglicy dzieją się dziwne rzeczy, magister i jego uczniowie uciekają, a zaraz potem cały teren roi się od tych magicznych bestyjek! A kto powiedział o tym Wyllithenowi? Nikt, ot co!$B$B$N, musisz mi pomóc pozbyć się części tego paskudztwa... Nie mogę dbać o teren, kiedy wszędzie szaleją te „anomalie”!', 'Zabij 6 węży many i 6 biesów eteru, a następnie wróć do ogrodnika Wyllithena na Ziemiach Krańca Mroku w Gaju Wszechpieśni.', '', 'Wróć do ogrodnika Wyllithena na Ziemiach Krańca Mroku w Gaju Wszechpieśni.', '', '', '', '', 0),
(8895, 'koKR', 'Przesyłka do Północnego Sanktuarium', 'Miło mi odkryć, że jesteś choć trochę $gkompetentny:kompetentna;, $N. Skoro tak ci pilno się wykazać, dam ci kolejne zadanie.$B$BTo list do opiekuna linii mocy Caidanisa, arkanisty odpowiedzialnego za utrzymanie Północnego Sanktuarium. Znajdziesz go na południowy zachód od Placu Sokolego Skrzydła. To bardzo ważna osobistość, więc mam nadzieję, że nie będziesz go zanadto zanudzać błahą paplaniną.', 'Dostarcz nieoznaczony list opiekunowi linii mocy Caidanisowi w Północnym Sanktuarium w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(8896, 'koKR', 'Krasnoludzki szpieg', 'Na pewno $gznalazłeś:znalazłaś; te notatki przy nocnym elfie? Większość z nich napisano po krasnoludzku...$B$BPoszukiwacz Kowadłostróż! Przysłano go tu z Żelaznej Kuźni z misją dyplomatyczną. Trzeba było się domyślić, że jego zainteresowanie naszymi tajemnymi sanktuariami jest nieco przesadne. $N, odszukaj krasnoluda w Północnym Sanktuarium i rozpraw się z nim. Aha, i zrób to dyskretnie.', 'Odszukaj i zabij poszukiwacza Kowadłostroża w Północnym Sanktuarium, a następnie złóż raport Aeldonowi Słonecznemu Piętnu w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9035, 'koKR', 'Zasadzka przy drodze', 'Ty tam! Musisz mi pomóc, błagam!$B$BNędzni napadli mnie i innego ucznia! W swoim obłąkańczym głodzie magii zabrali wszystko, co wpadło im w ręce: kryształy many, różdżki, księgi zaklęć... wszystko!$B$BMeledor ruszył za nimi w pościg; ja musiałem zostać i pilnować tego, czego nie zabrali. Idź dalej drogą i zobacz, czy zdołasz mu pomóc.', 'Porozmawiaj z uczniem Meledorem w Gaju Wszechpieśni, przy drodze prowadzącej na południe od Srebrnej Luny.', '', '', '', '', '', '', 0),
(9062, 'koKR', 'Przemoczone stronice', 'Ci przeklęci Nędzni potrafią naprawdę szybko uciekać na widok kogoś, kto im się postawi. Ale nie martwmy się tym teraz. Muszę odnaleźć grimuar żywiołów mojego instruktora.$B$BJestem pewien, że widziałem, jak jeden z tych tchórzy wrzucił go do rzeki, ale nie mogę go znaleźć. Przydałaby mi się dodatkowa para oczu. Dorzucę trochę monet, jeśli go wypatrzysz.', 'Uczeń Meledor w Gaju Wszechpieśni chce, żebyś $gprzeszukał:przeszukała; wodę pod pobliskim mostem i $gprzyniósł:przyniosła; mu grimuar żywiołów Antheola.', '', 'Wróć do ucznia Meledora w Gaju Wszechpieśni.', '', '', '', '', 0),
(9064, 'koKR', 'Wziąć winę na siebie', 'Antheol wpadnie w szał, kiedy się dowie, że jego księga jest zniszczona. Mam dla ciebie małą propozycję; nie martw się, opłaci ci się.$B$BZanieś mu tę księgę i nie mów ani słowa o tym, co się stało. Jeśli zapyta, powiedz po prostu, że $gupuściłeś:upuściłaś; ją w kałużę. Nie ma nad tobą bezpośredniej władzy, więc niewiele może ci zrobić.$B$BAntheol prowadzi wykłady nad Stawem Cichego Szeptu, na południowy wschód od Srebrnej Luny. Zrobisz to dla nas, prawda? Sowicie ci się odwdzięczę!', 'Zanieś grimuar żywiołów Antheola instruktorowi Antheolowi nad Stawem Cichego Szeptu w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9066, 'koKR', 'Szybka nauczka', 'Mam nadzieję, że wyciągniesz dziś cenną lekcję, $N. Nigdy nie licz na to, że ktoś inny skłamie za ciebie.$B$BA teraz chcę, żebyś $gwrócił:wróciła; do moich dwóch tępych uczniów i $gukarał:ukarała; ich tą rózgą. Moja magia podpowiada mi, że znajdziesz ich przy drodze na zachodzie, po drugiej stronie Trupiej Blizny.$B$BGdy to zrobisz, wróć do mnie. Dostaniesz skromną nagrodę za fatygę.', 'Użyj dyscyplinującej rózgi Antheola na jego dwóch uczniach: uczniu Ralenie i uczniu Meledorze. Następnie wróć z rózgą do Antheola nad Stawem Cichego Szeptu w Gaju Wszechpieśni.', '', 'Wróć do instruktora Antheola nad Stawem Cichego Szeptu w Gaju Wszechpieśni.', 'Uczeń Meledor ukarany', 'Uczeń Ralen ukarany', '', '', 0),
(9067, 'koKR', 'Przyjęcie bez końca', 'Uwielbiam wydawać przyjęcia... ot, drobnostka dla uczczenia wspaniałości, jaką jest Quel\'Thalas!$B$BAle znalazłem się w pewnym kłopocie. Potrzebuję, żebyś $gzebrał:zebrała; więcej zapasów na przyjęcie.$B$BOd mistrza winnic Muśniętego Słońcem z karczmy w Srebrnej Lunie przynieś mi butelkę specjalnej rezerwy muśniętej słońcem. Od Zalene Pierwszy Brzask z Ustronia Obieżyświatów zdobądź więcej tych wyśmienitych przystawek ze skoczołapa. Możesz też odebrać moją dostawę fajerwerków od Halisa Świtokrocza w Wiosce Rześkiej Bryzy.$B$BTylko się pospiesz!', 'Zdobądź butelkę specjalnej rezerwy muśniętej słońcem, przystawki ze skoczołapa i wiązkę fajerwerków, a następnie zanieś je lordowi Saltherilowi w Azylu Saltherila w Gaju Wszechpieśni.', '', 'Wróć do lorda Saltherila w Azylu Saltherila w Gaju Wszechpieśni.', '', '', '', '', 0),
(9076, 'koKR', 'Herszt Nędznych', 'Nędzni są tak otumanieni, tak objadają się plugawą magią, że nawet nie zauważyli, iż odzyskaliśmy większość broni. Nie możemy jednak liczyć, że długo pozostaną w tym otępieniu. Nadszedł czas na zdecydowany atak. Zróbmy przykład z ich przywódcy, Aldarona. Widziano go na najwyższym piętrze budynku przy przystani. Przynieś mi jego głowę, a sowicie cię wynagrodzę.', 'Przynieś głowę Aldarona Velendrisowi Białemu Porankowi w pobliżu Przystani Słonecznego Żagla w Gaju Wszechpieśni.', '', 'Wróć do Velendrisa Białego Poranka w Gaju Wszechpieśni.', '', '', '', '', 0),
(9119, 'koKR', 'Awaria w Zachodnim Sanktuarium', 'Skoro już tu jesteś, $N, mam do ciebie prośbę. Uczeń opiekunki linii mocy Velanii zajrzał tu wcześniej z prośbą o pomoc. Najwyraźniej w Zachodnim Sanktuarium doszło do jakiejś awarii. Byłem nieco zajęty zabawianiem naszego... jakże uroczego... krasnoludzkiego gościa. Zobacz, czy zdołasz jej pomóc. Zachodnie Sanktuarium znajdziesz na południowy zachód stąd.', 'Porozmawiaj z opiekunką linii mocy Velanią w Zachodnim Sanktuarium w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9144, 'koKR', 'Zaginiony na Widmowych Ziemiach', 'Mojego bratanka wysłano kilka dni temu na Widmowe Ziemie. Nigdy nie wspominał o swoim zadaniu, poza tym, że jest ściśle tajne.$B$BNie wrócił i obawiam się najgorszego, $N. Zaginiony posłaniec może niewiele znaczyć dla nieczułych magistrów Srebrnej Luny, ale dla mnie jest jak syn. Proszę, $N, czy go odszukasz?', 'Podążaj drogą z Wioski Rześkiej Bryzy na południe i wypatruj kuriera Świtokrocza w pobliżu Widmowych Ziem.', '', '', '', '', '', '', 0),
(9147, 'koKR', 'Powalony kurier', 'Czemu tak stoisz? Nie widzisz, że ten chłopak potrzebuje natychmiastowej pomocy? Wygląda na to, że zaraza zaczyna opanowywać jego ciało. Za kilka minut nawet mistrzyni aptekarstwa taka jak ja nie zdoła go uratować.$B$BWszystkie zwierzęta na południe od rzeki mają zarazę we krwi. Przejdź przez most i poluj tam na zadżumione bestie. Przynieś mi wystarczająco dużo próbek zadżumionej krwi, a wydestyluję surowicę, która uratuje tego krwawego elfa. Pośpiesz się!', 'Aptekarka Thedra w Gaju Wszechpieśni chce, żebyś $gprzyniósł:przyniosła; jej 4 próbki zadżumionej krwi od bestii z Widmowych Ziem.', '', 'Wróć do aptekarki Thedry w Gaju Wszechpieśni.', '', '', '', '', 0),
(9148, 'koKR', 'Przesyłka do Trankwillienu', 'Jestem... zbyt słaby, by iść dalej. Niosę złowieszcze ostrzeżenie od lorda regenta Therona – list. Musisz go dostarczyć za mnie.$B$BZanieś go arkaniście Vandrilowi w Trankwillienie. Miasto leży dalej na południe przy tej drodze. Idź tam i... odszukaj Vandrila...', 'Zanieś list ze Srebrnej Luny arkaniście Vandrilowi w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9252, 'koKR', 'Obrona Wioski Rześkiej Bryzy', 'Ataki Plagi wyraźnie się nasiliły, $N. Nasza obrona ledwie się trzyma, a ze Srebrnej Luny nie widać żadnych posiłków. Pomóż nam bronić wioski i przetrzeb nieumarłych krążących po pobliskiej Trupiej Bliźnie.', 'Zabij 4 zgniłoczłonych grabieżców i 4 mroczne upiory, a następnie wróć do tropicielki Sareyn w Wiosce Rześkiej Bryzy w Gaju Wszechpieśni.', '', 'Wróć do tropicielki Sareyn w Wiosce Rześkiej Bryzy w Gaju Wszechpieśni.', '', '', '', '', 0),
(9253, 'koKR', 'Strażnik run Deryan', 'Ten wzrost liczby ataków Plagi każe mi przypuszczać, że doszło do awarii jednego z kamieni runicznych chroniących granicę z Widmowymi Ziemiami.$B$BTe pradawne kamienie chroniły nas przed nieumarłymi. Większość z nich zniszczono lub utracono po ataku na Słoneczną Studnię.$B$BIdź drogą na południe, w stronę Widmowych Ziem, i wypatruj po zachodniej stronie wąskiej ścieżki. Przy pobliskim kamieniu runicznym znajdziesz strażnika run Deryana; on będzie wiedział, czy coś jest nie tak.', 'Porozmawiaj ze strażnikiem run Deryanem w Gaju Wszechpieśni, w pobliżu granicy z Widmowymi Ziemiami.', '', '', '', '', '', '', 0),
(9254, 'koKR', 'Krnąbrna uczennica', 'Dziękuję za pomoc, $N. Gdy ja będę tu przywracać porządek, chciałabym cię prosić o przysługę. Jedna z moich dawnych uczennic podjęła się bardzo niebezpiecznych badań. Udała się do Wschodniego Sanktuarium, w samym środku Trupiej Blizny.$B$BMartwię się o nią. Spróbuj ją odnaleźć i przemówić jej do rozsądku.', 'Porozmawiaj z uczennicą Mirvedą we Wschodnim Sanktuarium w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9255, 'koKR', 'Notatki badawcze', 'Choć wyniki moich badań są zniechęcające, zawierają cenne dane. Muszę je dać do oceny jakiemuś magistrowi, zanim ktokolwiek potraktuje je poważnie. Proszę, zanieś te notatki magistrix Landrze Świtokrocz w Wiosce Rześkiej Bryzy, na zachód stąd.', 'Dostarcz notatki badawcze magistrix Landrze Świtokrocz w Wiosce Rześkiej Bryzy w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9256, 'koKR', 'Wioska Rześkiej Bryzy', 'Mam dla ciebie kolejne zadanie, $N. Tropiciela Degoliena wysłano do Wioski Rześkiej Bryzy, by dowiedział się więcej o ataku Nędznych na pobliską stocznię. Poprosił o posiłki, których na razie nie możemy mu zapewnić. Odszukaj go i udziel mu wszelkiej pomocy, jaką zdołasz.$B$BDo Wioski Rześkiej Bryzy dotrzesz, idąc drogą z Placu Sokolego Skrzydła cały czas na południe. Powodzenia, $N.', 'Porozmawiaj z tropicielem Degolienem w Wiosce Rześkiej Bryzy w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9258, 'koKR', 'Spalony Gaj', 'Ekspansję Plagi na nowe tereny poprzedza plugawe skażenie gleby. Kamienie runiczne wzdłuż granicy z Widmowymi Ziemiami chroniły dotąd ziemię przed tym skażeniem.$B$BNajdalej wysunięty na zachód kamień runiczny został zniszczony podczas ataku Plagi, więc musieliśmy wypalić ziemię wokół niego, by skażenie się nie rozprzestrzeniło.$B$BMoja siostra, Larianna Rzecznowiew, czuwa nad Spalonym Gajem. Odszukaj ją; może mieć dla ciebie jakieś zadanie.', 'Odszukaj Lariannę Rzecznowiew w pobliżu Spalonego Gaju w południowo-zachodniej części Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9352, 'koKR', 'Darnasyjscy intruzi', 'Poza nieustannym zagrożeniem ze strony Nędznych muszę się jeszcze zajmować wszelkiej maści zmyślonymi doniesieniami o nocnych elfach.$B$BChoć większość doniesień jest bezpodstawna, jeden niedawny incydent wymaga dokładniejszego zbadania. W Zachodnim Sanktuarium, jednym z naszych głównych źródeł energii, doszło do poważnej awarii i szerzą się pogłoski o darnasyjskim sabotażu.$B$BUdaj się tam i rozpraw się z każdym, kto wygląda podejrzanie. Złóż raport opiekunce linii mocy Velanii, która czuwa nad sanktuarium.', 'Udaj się do Zachodniego Sanktuarium, na południowy zachód od Placu Sokolego Skrzydła, i pokonaj wszystkich intruzów, których tam zastaniesz. Przedstaw swoje ustalenia opiekunce linii mocy Velanii.', '', 'Wróć do opiekunki linii mocy Velanii w Zachodnim Sanktuarium w Gaju Wszechpieśni.', 'Intruz pokonany', '', '', '', 0),
(9357, 'koKR', 'Zgłoś się do Aeldona Słonecznego Piętna', 'Jeśli szukasz pracy, kapitana Słoneczne Piętno znajdziesz za Wewnętrzną Elfią Bramą, za drzwiami za moimi plecami.$B$BA teraz zostaw mnie w spokoju, muszę przesłuchać tego łajdaka.', 'Zgłoś się do Aeldona Słonecznego Piętna przy Wewnętrznej Elfiej Bramie w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9358, 'koKR', 'Tropicielka Sareyn', 'Nie uważaj bezpieczeństwa tej wioski za pewnik. Od wschodu oblega nas Plaga, a od zachodu Nędzni.$B$BTropicielka Sareyn strzeże naszych granic przed nieumarłymi, którzy napływają z Trupiej Blizny. Wyjdź z wioski drogą na wschód i zobacz, czy zdołasz jej pomóc.', 'Zgłoś się do tropicielki Sareyn na obrzeżach Wioski Rześkiej Bryzy w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9359, 'koKR', 'Ustronie Obieżyświatów', 'Twoja pomoc w poskramianiu Nędznych okazała się bezcenna. Obieżyświaci z pewnością znajdą zajęcie dla kogoś takiego jak ty w walce z trollami Amanów.$B$BUdaj się do Ustronia Obieżyświatów na północny wschód stąd, porozmawiaj z porucznik Świtobieżną i zobacz, jakiej pomocy potrzebuje.', 'Zgłoś się do porucznik Świtobieżnej w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9360, 'koKR', 'Inwazja Amanów', 'Choć nie rozumiesz języka, w którym spisano te plany bitewne, wyraźnie rozpoznajesz mapę z zaznaczonym położeniem Ustronia Obieżyświatów i Wioski Rześkiej Bryzy.$B$BLepiej powiadom o tym porucznik Świtobieżną w Ustroniu Obieżyświatów.', 'Dostarcz plany inwazji Amanów porucznik Świtobieżnej w Ustroniu Obieżyświatów.', '', '', '', '', '', '', 0),
(9363, 'koKR', 'Ostrzeżenie dla Wioski Rześkiej Bryzy', 'Udaj się do Wioski Rześkiej Bryzy i powiadom tropiciela Degoliena o planach Amanów. Nawet po śmierci Zul\'Marosha Wioska Rześkiej Bryzy musi się przygotować na atak trolli. Przekaż Degolienowi, że wyślę mu posiłki najszybciej, jak to możliwe.', 'Udaj się do Wioski Rześkiej Bryzy w Gaju Wszechpieśni i porozmawiaj z tropicielem Degolienem.', '', '', '', '', '', '', 0),
(9392, 'koKR', 'Szkolenie łotra', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych łotrów na Wyspie Słońcobieżców szkoli czatownik Kariel. Porozmawiaj z Karielem i sprawdź, czego może cię nauczyć. Jego lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BKariel – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z czatownikiem Karielem, nauczycielem łotrów, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(9393, 'koKR', '', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych łowców na Wyspie Słońcobieżców szkoli tropicielka Sallina. Porozmawiaj z Salliną i sprawdź, czego może cię nauczyć. Jej lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BSallina – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z tropicielką Salliną, nauczycielką łowców, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(9394, 'koKR', 'Gdzie jest Wyllithen?', 'Ogrodnik z Krańca Mroku zaginął! Ktoś musiał zapomnieć mu powiedzieć, żeby odszedł razem z magistrem i całą resztą. Wiem, że wciąż jest gdzieś tu na terenie, ale nie śmiem sama go szukać, skoro wszędzie krążą te magiczne stworzenia.$B$BOdnajdziesz go dla mnie, $N, i sprawdzisz, czy nic mu nie jest?', 'Odnajdź ogrodnika Wyllithena na Ziemiach Krańca Mroku w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9395, 'koKR', 'Azyl Saltherila', 'Przysięgam, że jeśli dostanę jeszcze jedną prośbę od lorda Saltherila w sprawie zapasów na jego przyjęcie, ktoś oberwie kulą ognia! Czy ja wyglądam na organizatorkę przyjęć?! Tak między nami, ten głupiec i jego pochlebcy udają, że nikt nas tu nie atakuje!$B$BNiektórzy z nas są naprawdę zajęci, no nie wiem, na przykład obroną tego, co zostało z Quel\'Thalas! $N, czy $gmógłbyś:mogłabyś; udać się do Azylu Saltherila i sprawić, żeby wreszcie się zamknął? To kawałek dalej drogą na zachód.', 'Porozmawiaj z lordem Saltherilem w Azylu Saltherila w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(9402, 'koKR', 'Aport!', 'A więc... $n, tak? Nie pochlebiaj sobie, że znam twoje imię – jedna z moich uczennic wzdycha do ciebie i nie potrafi przestać o tobie paplać.$b$bHmm... jeśli chcesz $gjej:jemu; zaimponować, może zrobisz coś dla mnie? Na dnie stawu za moimi plecami leży lazurowa fiolka. Zanurkuj, wyłów ją i przynieś tutaj.', 'Zanurkuj na dno Stawu Cichego Szeptu i wyłów lazurową fiolkę dla instruktora Antheola.', '', 'Wróć do instruktora Antheola nad Stawem Cichego Szeptu w Gaju Wszechpieśni.', '', '', '', '', 0),
(9403, 'koKR', 'Najczystsza woda', 'Skoro już $godebrałeś:odebrałaś; małą lekcję, zaproponuję ci coś bardziej konkretnego. Chodzi o twoją umiejętność obrony w walce wręcz. Oczywiście po walkę wręcz należy sięgać tylko w ostateczności, ale to żadna wymówka, by nie być na nią przygotowanym.$b$bMogę ci pomóc stworzyć kostur godny maga o twojej wiedzy. Weź po prostu fiolkę, którą mi $gprzyniosłeś:przyniosłaś;, i napełnij ją u stóp Wodospadów Elrendar. Idź wzdłuż rzeki na południowy wschód stąd.', 'Instruktor Antheol chce, żebyś $gnapełnił:napełniła; lazurową fiolkę przy Wodospadach Elrendar.', '', 'Wróć do instruktora Antheola nad Stawem Cichego Szeptu w Gaju Wszechpieśni.', '', '', '', '', 0),
(9404, 'koKR', 'Jeszcze niedawno żywe', 'Być może $gzauważyłeś:zauważyłaś; chodzące drzewa w pobliżu Wodospadów Elrendar. Jako strażnicy natury przesiąknięte są pierwotną magią, którą możemy przekształcić na własny użytek za pomocą czystej wody, którą już mi $gprzyniosłeś:przyniosłaś;.$b$bNiestety, zieloni strażnicy to sękate, powykręcane stwory, więc być może będziesz $gmusiał:musiała; zabić kilku, zanim znajdziesz gałąź nadającą się do użytku.', 'Zabijaj zielonych strażników Wszechpieśni, dopóki nie zdobędziesz żywej gałęzi dla instruktora Antheola.', '', 'Wróć do instruktora Antheola nad Stawem Cichego Szeptu w Gaju Wszechpieśni.', '', '', '', '', 0),
(9484, 'koKR', '', 'Z pewnością nieraz $gpolowałeś:polowałaś; na zwierzęta i $gzabijałeś:zabijałaś; je, by się bronić i wyżywić, lecz dopiero teraz jesteś w stanie się z nimi zaprzyjaźnić i zaprząc ich siłę do własnych celów. Tego mogę cię nauczyć.$b$bWeź tę magiczną różdżkę oswajania – pozwala ona na krótko związać się z dzikim zwierzęciem, które będzie walczyć u twego boku. Zacznij od oszalałego smoczego jastrzębia, niemal potulnego ptaka, którego znajdziesz tuż za Ustroniem Obieżyświatów. Gdy to zrobisz, wróć do mnie.', 'Użyj różdżki oswajania, by oswoić oszalałego smoczego jastrzębia, a następnie wróć do porucznik Świtobieżnej.', 'Oswój oszalałego smoczego jastrzębia', 'Wróć do porucznik Świtobieżnej w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', 0),
(9485, 'koKR', '', 'Dobrze się $gspisałeś:spisałaś;, $n. Szybko coraz lepiej rozumiesz dziką naturę.$b$bMglisty nietoperz to sprytny łowca, łączący szybkość smoczego jastrzębia z zajadłością skoczołapa. Mgliste nietoperze znajdziesz tuż za Rzeką Elrendar, na południu, gdzie polują na nieszczęsnych wędrowców zapuszczających się na Widmowe Ziemie.$b$bUżyj tej ostatniej różdżki oswajania, by zaprzyjaźnić się z mglistym nietoperzem, a gdy skończysz, wróć do mnie.', 'Użyj różdżki oswajania, by oswoić mglistego nietoperza, a następnie wróć do porucznik Świtobieżnej.', 'Oswój mglistego nietoperza', 'Wróć do porucznik Świtobieżnej w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', 0),
(9486, 'koKR', '', 'Stary skoczołap to sprawny i szybki łowca. Gdy spróbujesz się z nim zaprzyjaźnić, uzna cię za zdobycz. Nie daj się zniechęcić.$b$bUżyj różdżki oswajania, by przywołać wielkiego kota do swego boku i polować razem z nim. Spotkasz je w całym Gaju Wszechpieśni, niektóre tuż obok naszej siedziby. Gdy dość się nauczysz, wróć do mnie.', 'Użyj różdżki oswajania, by oswoić starego skoczołapa, a następnie wróć do porucznik Świtobieżnej.', 'Oswój starego skoczołapa', 'Wróć do porucznik Świtobieżnej w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', 0),
(9673, 'koKR', '', 'Poza nawiązaniem więzi z wybranym zwierzęciem pozostają jeszcze zawiłości opieki nad nim i jego szkolenia. W tym poprowadzi cię Halthenis, treser zwierząt w Srebrnej Lunie.$b$bZawsze okazuje najwyższy szacunek moim uczniom, jeśli oni okazują go jemu. Nie zawiedź mnie.', 'Porozmawiaj z Halthenisem w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(9676, 'koKR', '', 'W miarę jak będziesz się rozwijać w swojej klasie, warto korzystać ze szkoleń, które zapewnia nauczyciel klasy. Młodych paladynów na Wyspie Słońcobieżców szkoli Jesthenis Słońcobij. Porozmawiaj z Jesthenisem i sprawdź, czego może cię nauczyć. Jego lekcje kosztują, więc zabierz ze sobą trochę monet.$B$BTwój nauczyciel – podobnie jak wszyscy nauczyciele na Wyspie Słońcobieżców – przebywa na dolnym poziomie Słonecznej Iglicy.', 'Porozmawiaj z Jesthenisem Słońcobijem, nauczycielem paladynów, w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(9704, 'koKR', 'Ofiara Nędznych', 'Praca zwiadowcy między Wyspą Słońcobieżców a Placem Sokolego Skrzydła to ciężki kawałek chleba. Napięte terminy, długie godziny, a co najgorsze... Nędzni!$B$BDroga na południe wiedzie przez ruiny Srebrnej Luny... roi się tam od Nędznych gotowych zabić cię dla kilku kryształów many. Obawiam się, że właśnie to spotkało ostatnią zwiadowczynię, którą wysłaliśmy z jedną z paczek Erony.$B$BWidzę, że bardzo chcesz się wykazać. Zapuść się w Aleję Świtu i sprawdź, czy znajdziesz jakiś ślad naszej zwiadowczyni.', 'Udaj się na południe, do ruin Srebrnej Luny, i poszukaj poległej zwiadowczyni w Alei Świtu.', '', '', '', '', '', '', 0),
(9705, 'koKR', 'Odzyskanie paczki', 'Bierzesz paczkę i upewniasz się, że rzeczywiście pochodzi od magistrix Erony. Alarion zapewne chciałaby, żebyś jej ją $gprzyniósł:przyniosła;.', 'Wróć do zwiadowczyni Alarion z paczką Erony.', '', '', '', '', '', '', 0),
(10068, 'koKR', 'Wartownik Studni Solanian', 'A teraz musisz coś dla mnie zrobić.$B$BWartownik Studni Solanian potrzebuje twoich usług. Dobrze zrobisz, jeśli zaskarbisz sobie jego względy.$B$BCzeka na ciebie na zewnętrznym tarasie, na który prowadzi rampa z tej komnaty.', 'Porozmawiaj z wartownikiem Studni Solanianem w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(10069, 'koKR', 'Wartownik Studni Solanian', 'A teraz musisz coś dla mnie zrobić.$B$BWartownik Studni Solanian potrzebuje twoich usług. Dobrze zrobisz, jeśli zaskarbisz sobie jego względy.$B$BCzeka na ciebie na zewnętrznym tarasie, na który prowadzi rampa z tej komnaty.', 'Porozmawiaj z wartownikiem Studni Solanianem w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(10070, 'koKR', 'Wartownik Studni Solanian', 'A teraz musisz coś dla mnie zrobić.$B$BWartownik Studni Solanian potrzebuje twoich usług. Dobrze zrobisz, jeśli zaskarbisz sobie jego względy.$B$BCzeka na ciebie na zewnętrznym tarasie, na który prowadzi rampa z tej komnaty.', 'Porozmawiaj z wartownikiem Studni Solanianem w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(10071, 'koKR', 'Wartownik Studni Solanian', 'A teraz musisz coś dla mnie zrobić.$B$BWartownik Studni Solanian potrzebuje twoich usług. Dobrze zrobisz, jeśli zaskarbisz sobie jego względy.$B$BCzeka na ciebie na zewnętrznym tarasie, na który prowadzi rampa z tej komnaty.', 'Porozmawiaj z wartownikiem Studni Solanianem w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(10072, 'koKR', 'Wartownik Studni Solanian', 'A teraz musisz coś dla mnie zrobić.$B$BWartownik Studni Solanian potrzebuje twoich usług. Dobrze zrobisz, jeśli zaskarbisz sobie jego względy.$B$BCzeka na ciebie na zewnętrznym tarasie, na który prowadzi rampa z tej komnaty.', 'Porozmawiaj z wartownikiem Studni Solanianem w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(10073, 'koKR', 'Wartownik Studni Solanian', 'A teraz musisz coś dla mnie zrobić.$B$BWartownik Studni Solanian potrzebuje twoich usług. Dobrze zrobisz, jeśli zaskarbisz sobie jego względy.$B$BCzeka na ciebie na zewnętrznym tarasie, na który prowadzi rampa z tej komnaty.', 'Porozmawiaj z wartownikiem Studni Solanianem w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', '', '', '', '', '', 0),
(10166, 'koKR', 'Pamięć o Białej Korze', 'Ten wisior przywołuje wspomnienia innych czasów. Lepszych czasów.$B$BNiestety, wspomnienia to ostatnie, czego mi teraz trzeba.$B$BChcę, żebyś $gzakopał:zakopała; go przy kamieniu runicznym w Spalonym Gaju. To tam po raz pierwszy spotkałam starszego drzewców. Pozwól pamięci o moim starym przyjacielu spocząć w pokoju.', 'Larianna Rzecznowiew chce, żebyś $gumieścił:umieściła; wisior Starej Białej Kory przy kamieniu runicznym w Spalonym Gaju.', '', '', '', '', '', '', 0),
(10530, 'koKR', '', '', 'Porozmawiaj z porucznik Świtobieżną w Ustroniu Obieżyświatów w Gaju Wszechpieśni.', '', '', '', '', '', '', 0),
(14081, 'koKR', 'Nauka jazdy w Gaju Wszechpieśni', 'Tę ulotkę, zachwalającą naukę jazdy wierzchem i sprzedaż wierzchowców, przysłał Perascamin.$B$BPerascamina znajdziesz w Stajni Thurona, na południowy wschód od Bramy Pasterza, przy wyjściu ze Srebrnej Luny.', 'Zwróć ulotkę Perascaminowi w Stajni Thurona w Srebrnej Lunie.', '', 'Wróć do Perascamina w Gaju Wszechpieśni.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(8325, 'koKR', '$GUkończyłeś:Ukończyłaś; swoje pierwsze zadanie i należą ci się za to gratulacje. Taki sukces daje mi wiarę, że wyrośniesz na kogoś lepszego niż ci młodzi krwawi elfowie, którzy lekceważą nauki swoich mistrzów. Dalsze sukcesy zostaną nagrodzone – nie tylko wiedzą, lecz także czymś bardziej namacalnym.$B$BTwoja praca tutaj jednak się nie skończyła. Wiele jeszcze musisz się nauczyć, $gmój młody przyjacielu:moja młoda przyjaciółko;...', 0),
(8326, 'koKR', 'Wieża i jej okolice powinny być teraz względnie bezpieczne, choć tylko na jakiś czas. $GSpisałeś:Spisałaś; się dobrze, zapewniając nam nieco wytchnienia, lecz jeśli mamy tu przetrwać na dłuższą metę, musimy odzyskać władzę nad całą wyspą. A to oznacza zmierzenie się z zagrożeniami o wiele groźniejszymi niż zdziczałe żmije many i rysie.$B$BWeź to, $N – bez wątpienia zrobisz z tego dobry użytek w nadchodzących zadaniach.', 0),
(8327, 'koKR', 'Magistrix Erona mówiła, że wkrótce się zjawisz, $N. Akademia Falthrien na zachód stąd – ten ogromny, unoszący się w powietrzu gmach o zdobnych iglicach – jest w opłakanym stanie. Pokierujesz próbą odbicia jej z rąk jednego z Nędznych – elfa, który na zawsze uległ swoim najniższym żądzom.$B$BMam nadzieję, że jesteś $ggotów:gotowa; do pracy. Będzie to lekcja nie tylko o niebezpieczeństwie, lecz także o tym, co się dzieje, gdy wyprzesz się tego, kim naprawdę jesteś.', 0),
(8328, 'koKR', 'Ach, $N – jesteś $gjednym z nowych magów:jedną z nowych czarodziejek; na wyspie, prawda? $GTrafiłeś:Trafiłaś; we właściwe miejsce. Jeśli pragniesz mistrzostwa w tajemnej sztuce, mogę ci przekazać tę wiedzę – o ile stać cię na koszty szkolenia i potrafisz skupić się na lekcjach, których będę ci udzielać.$B$BZaczynajmy!', 0),
(8329, 'koKR', 'Witaj w Słonecznej Iglicy, $N! Tu i teraz zaczyna się nauka władania bronią i taktyki bitewnej. Od moich uczniów wymagam jedynie, by pokrywali koszty szkolenia i by umieli słuchać równie dobrze, jak pragną walczyć. Mam wiele do przekazania i nie lubię niepotrzebnie się powtarzać.$B$BZabierzmy się więc do dzieła!', 0),
(8330, 'koKR', 'Dobra robota – wiedziałem, że świetnie się do tego nadasz. Gdy korzystanie z naszych pracowni pod gołym niebem znów będzie bezpieczne, zrobię z tych rzeczy dobry użytek.$B$BJak wspominałem, torbę możesz zatrzymać. Może też przyda ci się ta część pancerza. Uznaj ją za sowitą zapłatę za proste zadanie, sumiennie wykonane!', 0),
(8334, 'koKR', 'Choć śmierć opiekunów nie sprawia mi żadnej radości, pokazuje, że jesteś $ggotów:gotowa; na najważniejsze zadanie, jakie wykonasz na Wyspie Słońcobieżców. Weź to i zrób z tego dobry użytek; w tym, co cię czeka, przydadzą ci się dobre przedmioty i bystry umysł. Od tego zależy, czy odzyskamy władzę nad wyspą.', 0),
(8335, 'koKR', 'Głowa Felendrena... należą ci się pochwały, $N. $GOdniosłeś:Odniosłaś; sukces tam, gdzie inni, jak Felendren, ponieśli sromotną klęskę. Być może naprawdę jesteś $ggotów:gotowa; stać się $gpożytecznym członkiem:pożyteczną członkinią; społeczności krwawych elfów.$B$BTwój sukces dowodzi, że zdołasz przetrwać groźniejsze niebezpieczeństwa czyhające w Gaju Wszechpieśni... a wierz mi, nie brakuje ich.', 0),
(8336, 'koKR', 'Znakomicie – doskonale się nadadzą. Sporo rozmyślałem nad niemocą, która dręczy obecnie Wyspę Słońcobieżców. Jednym z rozważanych przeze mnie kroków było zebranie tajemnych odłamków od stworzeń z wyspy. Można by przeprowadzić na nich doświadczenia, co pozwoliłoby może wskazać winowajcę.$B$BAle mniejsza z tym, zajmę się badaniami. Pozwól, że rzucę na ciebie to zaklęcie. Wierzę, że zrobisz z niego dobry użytek!', 0),
(8338, 'koKR', 'To jest... nader interesujące. A mówiąc „interesujące”, mam na myśli raczej „niepokojące”.$B$BOdzyskiwanie władzy nad wyspą po zniszczeniu Słonecznej Studni okazało się trudnym wyzwaniem. Podejrzewam, że u sedna wszystkiego leży jakieś plugawe źródło, które kazi wyspę; ten odłamek może pomóc odkryć, co tu się naprawdę dzieje.$B$B$GPostąpiłeś:Postąpiłaś; mądrze, przynosząc go do mnie, $N. Przyjmij to jako zapłatę za twoją sumienność. Dziękuję.', 0),
(8345, 'koKR', 'Ach, $N – dziękuję, że $gpodzieliłeś:podzieliłaś; się ze mną tym, czego $gdoświadczyłeś:doświadczyłaś; w Kaplicy Dath\'Remara. Przede wszystkim należy ci się uznanie za poczucie obowiązku i szacunek – przydadzą ci się nie tylko tutaj, lecz w całym Azeroth.$B$BCo zaś do tego dziwnego odczucia, bez wątpienia wiąże się ono ze skazą, która dotknęła Wyspę Słońcobieżców. Będziemy mieć to na oku; dziękuję, że nas $gostrzegłeś:ostrzegłaś;!', 0),
(8346, 'koKR', '$GSpisałeś:Spisałaś; się dziś dobrze, $N. Twoja chęć nauki pokazuje, że być może zdołasz wznieść się ponad nieustępliwe żądze, które jako $R musisz znosić.$B$BNie spoczywaj jednak na laurach, lecz dąż do mistrzostwa w tym, czego się $gnauczyłeś:nauczyłaś;. Tylko dzięki wytrwałości przetrwamy jako rasa.$B$BWeź to', 0),
(8347, 'koKR', 'No proszę, witaj, $N! Słyszałam, że ktoś zaradny, kto dotąd służył magistrix Eronie, może się tu zjawić, by pomóc nam, zwiadowcom. Chętnie przyjmiemy pomoc, zwłaszcza od kogoś, kto $gwykazał:wykazała; się takimi umiejętnościami.$B$BMam nadzieję, że zechcesz załatwić dla nas sprawę czy dwie.', 0),
(8350, 'koKR', 'Dziękuję, bardzo cenię sobie tak szybką dostawę.$B$BSkoro już tu jesteś, rozgość się. Jeśli jeszcze tego nie $gzrobiłeś:zrobiłaś;, możesz wziąć Kamień Powrotu i przypisać go do tej karczmy. Kamień Powrotu pozwala raz na godzinę przenieść się do karczmy. Jeśli go kiedyś zgubisz, wystarczy wrócić do dowolnej karczmy – karczmarz chętnie da ci nowy.', 0),
(8463, 'koKR', 'Znakomita robota, $N.', 0),
(8468, 'koKR', 'Ten łajdak Thaelis wreszcie dostał za swoje. Dobra robota, $N. Nędzni powinni się na jakiś czas uspokoić.', 0),
(8472, 'koKR', '$GSpisałeś:Spisałaś; się, $N. Skoro nasze tajemne sanktuaria nie działają w pełni, te rdzenie mocy w znacznym stopniu zaspokoją nasze potrzeby.', 0),
(8473, 'koKR', 'A więc stało się. Przeklęte niech będą czasy, które zmusiły nas do tak rozpaczliwych kroków... i przeklęty niech będzie nasz wróg, Plaga!$B$BZapamiętaj to, $N. Nasze ziemie trzeba chronić bez względu na cenę. Zwyciężymy!', 0),
(8474, 'koKR', 'Ten... ten wisior. Dałam go Starej Białej Korze, gdy jego lud pomógł nam odbudować wioskę.$B$BCzyli to znaczy, że on...$B$B<Krwawa elfka odchrząkuje, odzyskując panowanie nad sobą.>$B$BDziękuję, że mi go $gprzyniosłeś:przyniosłaś;, $N. Chciałabym cię o coś poprosić.', 0),
(8475, 'koKR', 'Nie spodziewamy się, by Plaga w najbliższym czasie osłabiła ataki, ale cenimy każdą pomoc w strzeżeniu Blizny.', 0),
(8476, 'koKR', 'Dobra robota, $N. Gdyby więcej było takich jak ty, wkrótce przywrócilibyśmy naszym ziemiom dawną chwałę.', 0),
(8477, 'koKR', 'Plotki mówią prawdę! Ten młot jest zarazem lekki i wytrzymały; zdołam ukończyć kilka niedokończonych dzieł. A ty, rzecz jasna, wybierasz pierwszy.', 0),
(8479, 'koKR', 'Tak, $gbrachu:siostro;. Zul\'Marosh sobie zasłużyć. On spalić wioskę Ven\'jashiego. Ja zabić wielu Amanów, zanim oni wsadzić mnie do tej klatki. Ja coś zakopać w piasku, to teraz mój prezent dla ciebie.$B$BAch... ach, trucizna... teraz się rozchodzić, mon. Czas odpocząć...', 0),
(8480, 'koKR', 'Świetna robota, $N. Pokażmy Nędznym, z jakiej gliny jesteśmy ulepieni!', 0),
(8482, 'koKR', 'Na pewno $gznalazłeś:znalazłaś; je przy nocnym elfie? Napisano je wyraźnie po krasnoludzku...$B$BO ile dobrze rozumiem ten list, jego autor nie spowodował awarii, lecz został tu przysłany jako szpieg, by obserwować jej skutki. Nazywa nasze przedsięwzięcia lekkomyślnymi i niebezpiecznymi... ale kto to napisał?$B$BOczywiście! Ten wysłannik z Żelaznej Kuźni! Byliśmy głupcami, ufając komukolwiek z Przymierza!', 0),
(8483, 'koKR', 'A więc stało się. Znakomita robota.$B$BWieść dotarła już do generała tropicieli i wierz mi, krasnoludy drogo zapłacą za swoją zdradę.$B$B$GOddałeś:Oddałaś; dziś swojemu ludowi wielką przysługę, $N.', 0),
(8486, 'koKR', 'Dziękuję, $N. Skoro upiory są już pod kontrolą, możemy wysłać kogoś, by ocenił szkody. Oby nie były trwałe.', 0),
(8487, 'koKR', 'Znakomicie. Rzucę na próbki zaklęcie wzmacniające, żeby dokładniej zbadać skażenie gleby.', 0),
(8488, 'koKR', 'Moje starania są daremne, $N. Sama natura gleby uległa zmianie... skażenie jest nieodwracalne. Dziękuję za pomoc. Muszę cię poprosić o jeszcze jedną, ostatnią przysługę.', 0),
(8490, 'koKR', 'Znakomicie. Nasza obrona powinna powstrzymać Plagę nieco dłużej. Dziękuję, że $gpodałeś:podałaś; nam pomocną dłoń, $N.', 0),
(8491, 'koKR', 'Doskonale się nadadzą, $N. Weź tę część pancerza w nagrodę. Ze skór, które $gprzyniosłeś:przyniosłaś;, zrobię kolejne.', 0),
(8563, 'koKR', '$N – doszły mnie słuchy, że szukasz mistrza w sztuce czarnoksięstwa. Wyglądasz na $gzdolnego:zdolną;, ale od uczniów oczekuję czegoś więcej niż wyglądu. Musisz być $ggotów:gotowa; zapuścić się tam, gdzie inni boją się zajrzeć, by zdobyć moc. Będę cię uczył, ale nie będę tolerował porażek.$B$BSzkolenie będzie wiązało się z kosztami, lecz bardziej powinna cię obchodzić cena, jaką gotów jest zapłacić twój umysł. Jeśli jesteś $ggotów:gotowa;, zaczynajmy.', 0),
(8564, 'koKR', 'Witaj, $N – jestem matrona Arena. Służę pomocą tym, którzy pragną zgłębić kapłańską ścieżkę. Często mylnie uważa się ją za drogę pacyfizmu, lecz w przypadku nas, krwawych elfów, nic nie może być dalsze od prawdy. Owszem, leczymy zarówno ciało, jak i ducha, ale jesteśmy też pięścią zemsty wymierzoną w tych, którzy odważą się przeciw nam wystąpić.$B$BBędę cię szkolić, proszę tylko, byś $gpokrywał:pokrywała; koszty szkolenia i $guczył:uczyła; się z otwartym umysłem. Jeśli się zgadzasz, możemy zaczynać.', 0),
(8884, 'koKR', 'Dobra robota. Sądząc po zapachu, $gprzyniosłeś:przyniosłaś; wszystko, o co prosiłem, a może i więcej. Na pewno znajdziemy dla nich jakieś zastosowanie – choćby w gulaszu czy czymś w tym rodzaju.$B$BNiestety, twoje wysiłki chyba nie przyniosły skutku; murloki wcale się nie wycofują. Trzeba działać bardziej zdecydowanie!', 0),
(8885, 'koKR', 'Nareszcie! Choć murloki Ponurej Łuski nie rzuciły się do ucieczki, jak liczyłem, zabawnie było patrzeć, jak wpadają w popłoch, gdy $gpowaliłeś:powaliłaś; ich tak zwanego wodza. Masz moją wdzięczność i wdzięczność sin\'dorei ze Srebrnej Luny!$B$BProszę, weź jedną z tych rzeczy w podziękowaniu za oddaną przysługę.', 0),
(8886, 'koKR', 'Udało ci się! $GUratowałeś:Uratowałaś; mnie przed ruiną i $gpomściłeś:pomściłaś; mnie na tych obrzydliwych stworach!$B$BGdybym tylko jeszcze namówiła tych przystojnych tropicieli, żeby pomogli mi z ładunkiem, wreszcie bym się stąd wyrwała! Będę musiała wrócić, gdy Velendris odbije stocznię.$B$BMasz, weź te monety. Tyle tylko mogę ci dać – to najmniej, czym mogę wynagrodzić twój trud.', 0),
(8887, 'koKR', 'Och, ty $gkochany:kochana;, $gkochany:kochana; $N! Nie miałam pojęcia, że te obrzydliwe murloki Ponurej Łuski porwały też moje locje nawigacyjne! Bez nich nie miałabym szans żeglować po morzach, gdy już odbijemy przystań i naprawimy statek.$B$BStokrotne dzięki! Weź te monety w dowód mojej wdzięczności.', 0),
(8888, 'koKR', 'Magister martwił się o mnie? Jakież to słodkie. Szkoda, że nie okazywał takiej troski wcześniej, gdy byliśmy w Iglicy.$B$BAle to teraz bez znaczenia. Posłuchaj uważnie, $N, bo mam do ciebie prośbę.', 0),
(8889, 'koKR', 'Jestem ci wdzięczna za pomoc, ale zasmuciła mnie wieść, że niektórzy z moich współuczniów ulegli nałogowi.$B$BSkoro Iglica jest odcięta od zasilania, chyba zostanę tu jeszcze trochę i zobaczę, czy uspokoi się na tyle, żebym mogła zakraść się do środka i zabrać ich szczątki.', 0),
(8890, 'koKR', 'Nie! Przybyłem za późno. To wszystko moja wina.$B$BMoje badania nad oczyszczaniem alternatywnych źródeł magii wymknęły się spod kontroli, zanim zdołałem je przerwać. Gdybym tylko poszedł tam sam... albo gdyby mnie posłuchali i wzięli sobie do serca moje ostrzeżenia!$B$BMam krew na rękach, $N. Dziękuję ci jednak, że $gukoiłeś:ukoiłaś; udręczone dusze moich dawnych uczniów. To marna, ale jednak pociecha, że nie będą trwać w stanie, w którym krwawemu elfowi lepiej byłoby umrzeć.', 0),
(8891, 'koKR', 'Oto on, $N – dowód mojej zbrodni. Ten dziennik zawiera wszystkie moje nierozważne badania.$B$BGłuchy na ostrzeżenia, prowadziłem je dalej, dopóki niemal nie było za późno. Gdy zrozumiałem swój błąd, zrobiłem, co mogłem. Lecz wtedy niektórzy z moich uczniów zaszli już za daleko. Ewakuowałem Iglicę, by odsunąć ich od skażenia, ale w pośpiechu zapomniałem wyłączyć źródła mocy.$B$BSpalę tę księgę, by nikt więcej nie padł ofiarą jej treści. Chciałem tylko pomóc sin\'dorei.', 0),
(8892, 'koKR', 'To ich nauczy, żeby z nami nie zadzierać. Dobra robota, $N.', 0),
(8894, 'koKR', 'No cóż, chyba musi to wystarczyć, prawda? Dzięki za pomoc, $N. Mogę tylko mieć nadzieję, że zdążę posprzątać cały ten bałagan, zanim magister wróci do Iglicy Krańca Mroku.$B$BWeź te drobniaki; to niewiele, ale nic więcej teraz nie mam. A jeśli $gbyłbyś:byłabyś; tak $guprzejmy:uprzejma;, rozpraw się po drodze z jeszcze kilkoma bestyjkami.', 0),
(8895, 'koKR', 'Dziękuję, $N. Czekałem na ten list.', 0),
(9035, 'koKR', 'Uciekli. Napędziłem im stracha celnie posłaną kulą ognia! Niestety, wrzucili nasz cenny ładunek do rzeki.', 0),
(9062, 'koKR', 'Księga jest kompletnie przemoczona. Instruktorowi Antheolowi wcale się to nie spodoba.$B$BMasz, weź te pieniądze. Mam pewien pomysł.', 0),
(9064, 'koKR', 'Mówisz, że tych dwóch nieudolnych głupców przekupiło cię, żebyś mnie $gokłamał:okłamała;? Bardzo dobrze $gzrobiłeś:zrobiłaś;, przychodząc z tym do mnie, $N.', 0),
(9066, 'koKR', 'Znakomita robota, $N. Nie martw się, nie utkną w tej postaci na zawsze. Tytułu uczniów jednak nie odzyskają, dopóki znów na niego nie zasłużą.', 0),
(9067, 'koKR', 'Ależ z ciebie $genergiczny młodzieniec:energiczna młoda dama;, prawda?$B$BWszystko to wygląda całkiem zadowalająco. Bez wątpienia należy ci się zapłata za zebranie tego wszystkiego, a do tego, jak sądzę, mały dodatek.$B$BAch, o mało nie zapomniałem – oto zaproszenie na przyjęcie. I, $N, gdy następnym razem wpadniesz, zadbaj o nieco bardziej... odświętny strój.', 0),
(9076, 'koKR', 'Jednak go $gpokonałeś:pokonałaś;! Bez wątpienia moi ludzie zmiękczyli go dla ciebie.$B$BŻartuję, $N. $GSpisałeś:Spisałaś; się. Wyrobisz sobie imię, jeśli nie wpakujesz się w kłopoty.', 0),
(9119, 'koKR', 'Rozejrzyj się. Nie wszystko jest tu w należytym porządku.$B$BW Zachodnim Sanktuarium doszło do poważnej awarii. Zróbmy, co w naszej mocy, by sprawy nie przybrały gorszego obrotu.', 0),
(9144, 'koKR', 'Pomóż mi, $gnieznajomy:nieznajoma;... Muszę... dotrzeć do Trankwillienu... Nie mogę zawieść.$B$B<Krwawy elf znów traci przytomność, a jego oczy zachodzą mgłą.>', 0),
(9147, 'koKR', 'W ostatniej chwili, $N! Już miałam zacząć kopać dół dla naszego przyjaciela.$B$BMój wywar chyba działa; odzyskuje przytomność.$B$BHej, chyba próbuje zwrócić twoją uwagę. Może z nim porozmawiasz?', 0),
(9148, 'koKR', 'Nareszcie! Całymi tygodniami czekaliśmy na odpowiedź lorda regenta! Zobaczmy...$B$B<Vandril zaczyna czytać list.>$B$BCo to ma być? Mroczna obecność? Wyczuwa mroczną obecność na Widmowych Ziemiach?! Bez żartów, sam mogłem mu to powiedzieć!$B$BI na to czekaliśmy?', 0),
(9252, 'koKR', 'Stokrotne dzięki, $N. Nikt nam nie dziękuje za naszą pracę, ale dziś $gpomogłeś:pomogłaś; nam ją nieco ułatwić.', 0),
(9253, 'koKR', 'Musiał cię przysłać ktoś z Wioski Rześkiej Bryzy. Wiedziałem, że to tylko kwestia czasu, zanim nadejdzie pomoc.', 0),
(9254, 'koKR', 'Jak miło, że moja dawna mistrzyni troszczy się o mnie. Szkoda tylko, że dawno straciła wiarę w moje badania.$B$BNie trać czasu na namawianie mnie do powrotu; możesz mi pomóc w badaniach albo odejść.', 0),
(9255, 'koKR', 'Te notatki... są wstrząsające. Jeśli są prawdziwe, szkody wyrządzone ziemi na Trupiej Bliźnie są nieodwracalne.$B$BNatychmiast powiadomię wielkiego magistra. To kolejny powód, by nasza rasa opuściła ten świat i odnalazła swoje prawdziwe przeznaczenie w Rubieży.', 0),
(9256, 'koKR', 'Dzięki, że $gprzybyłeś:przybyłaś;, $N. Sprawy wyglądają gorzej, niż przewidywaliśmy. Nędzni opanowali całą Przystań Słonecznego Żagla.', 0),
(9258, 'koKR', 'Ach, przysłał cię mój brat. Owszem, mam zadanie, przy którym przyda mi się pomoc.', 0),
(9352, 'koKR', 'Nocne elfy? Tutaj? Te szczury!$B$BMyślisz, że mają coś wspólnego z awarią w moim sanktuarium? Jeśli masz jakieś informacje, lepiej natychmiast zanieś je kapitanowi Słonecznemu Piętnu!', 0),
(9358, 'koKR', '$GPrzybyłeś:Przybyłaś;, żeby nam pomóc? Czemu nie mówisz od razu? Każda para rąk się przyda!', 0),
(9359, 'koKR', '$GPrzybyłeś:Przybyłaś; pomóc? Znakomicie!$B$BWalka z trollami Amanów dała nam się we znaki, a ktoś tak zdolny do walki jak ty zawsze jest mile widziany.', 0),
(9360, 'koKR', 'Trolle trzymały nas tu w szachu, a tymczasem planowały atak na Wioskę Rześkiej Bryzy. Zupełnie się tego nie spodziewaliśmy.', 0),
(9363, 'koKR', 'Informacje, które $gprzyniosłeś:przyniosłaś;, mają ogromne znaczenie, $N. Teraz, gdy znamy plany trolli, możemy przygotować się na atak.$B$BNie dadzą rady nas zaskoczyć.', 0),
(9392, 'koKR', 'Słyszałem, jak cienie szepczą twoje imię, $N. Podobno szukasz kogoś doświadczonego, kto wprowadzi cię w arkana fachu – kogoś takiego jak ja. Mogę to zrobić, ale za każdym razem, gdy będę miał cię czegoś nauczyć, oddasz mi niewielką działkę z twoich łupów. A więc tak, nauczę cię, co znaczy być łotrem.$B$BAle pamiętaj: jeśli kiedyś złapią cię na kradzieży, ta rozmowa nigdy się nie odbyła. A teraz ruszaj i pokaż mi, na co cię stać!', 0),
(9393, 'koKR', '$N, czy twój wzrok jest bystry jak u jastrzębia, ruchy zwinne jak u małpy, a szybkość równa szybkości geparda? Moje są, a twoje też mogą być – przy właściwym szkoleniu. Droga łowcy to panowanie nad zwierzętami tego świata, niezrównana precyzja strzału i wiedza o tym, jak przetrwać tam, gdzie inni by zginęli.$B$BJeśli tego właśnie pragniesz się nauczyć, będę cię szkolić – rzecz jasna za niewielką opłatą. Zaczynamy?', 0),
(9394, 'koKR', 'Kim jesteś? Na pewno nie jednym z uczniów magistra, to pewne!$B$BBez wątpienia przysłano cię, żebyś $gpomógł:pomogła; mi posprzątać ten bałagan!', 0),
(9395, 'koKR', 'Ach, jak miło, że magistrix Świtokrocz raczyła wreszcie odpowiedzieć na moje skromne prośby. Powinienem porozmawiać o jej zachowaniu z lordem regentem w Srebrnej Lunie. Jest doprawdy nieuprzejma!$B$BNie musisz się tym jednak kłopotać. Skoro już tu jesteś, może wreszcie dostanę te zapasy na przyjęcie, na które tak długo czekam?', 0),
(9402, 'koKR', 'Och, brawo... Kazałem ci skoczyć do stawu, a ty $gskoczyłeś:skoczyłaś;. Strach pomyśleć, co byś $gzrobił:zrobiła;, gdyby poprosił cię o to któryś z twoich dobrych przyjaciół.$B$BJeśli chcesz nagrody za swój trud, oto ona: nigdy nie kiwnij palcem, dopóki nie wiesz, co z tego będziesz mieć. Umysł maga to jego największa broń. Zapamiętaj to i staraj się używać swojego nieco częściej.', 0),
(9403, 'koKR', 'Zobaczmy, co mi $gprzyniosłeś:przyniosłaś;...$B$B<Unosi fiolkę pod światło i uważnie się jej przygląda.>$B$BTak, nada się. Dobra robota, $N.', 0),
(9404, 'koKR', '$GZrobiłeś:Zrobiłaś; to, o co prosiłem, $N, możesz więc teraz odebrać nagrodę.', 0),
(9484, 'koKR', 'To, że $gzniosłeś:zniosłaś; liczne ciosy szponów i ukąszenia smoczego jastrzębia, świadczy o twojej wytrwałości. Czy masz w sobie dość siły, by uczyć się dalej?', 0),
(9485, 'koKR', '$GSam:Sama; widzisz, $N, że na razie nie mam cię już czego uczyć. Rozumiesz już, co znaczy zaprzyjaźnić się z tymi, na które niegdyś się polowało. Musisz tylko wybrać jednego ze sprzymierzeńców natury, którego cechy odpowiadają twoim.', 0),
(9486, 'koKR', '$GWykazałeś:Wykazałaś; się zarówno siłą, jak i wytrwałością. Pozostała ostatnia próba, zanim zdołasz oswajać bez pomocy magii.', 0),
(9673, 'koKR', 'A więc czegoś się już $gnauczyłeś:nauczyłaś;, tak?$B$B<Halthenis przygląda ci się uważnie.>$B$BDzięki nowo nabytym umiejętnościom dobrze przysłużysz się miastu i naszej wyższej sprawie. Pozwól, że pokażę ci, jak nauczyć zwierzę kilku ciekawych sztuczek – na przykład patroszenia wrogów – a potem możesz ruszać w drogę.', 0),
(9704, 'koKR', 'Wszystkie rzeczy zwiadowczyni zostały skradzione, z wyjątkiem jednej paczki. Wygląda na to, że pasuje do opisu paczki Erony, który podała Alarion.', 0),
(9705, 'koKR', 'Na Słoneczną Studnię! To już trzecia zwiadowczyni, którą straciliśmy w tym miesiącu.$B$BDoceniam twoją odwagę – zapuszczenie się w Aleję Świtu to nie przelewki. Straże powinny baczniej pilnować tych przeklętych Nędznych.', 0),
(10068, 'koKR', 'Ach, świetnie – oto i $c. Spodziewałem się ciebie.$BMam kilka zadań, do których szczególnie się nadajesz.', 0),
(10069, 'koKR', 'Ach, świetnie – oto i $c. Spodziewałem się ciebie.$B$BMam kilka zadań, do których szczególnie się nadajesz.', 0),
(10070, 'koKR', 'Ach, świetnie – oto i $c. Spodziewałem się ciebie.$B$BMam kilka zadań, do których szczególnie się nadajesz.', 0),
(10071, 'koKR', 'Ach, świetnie – oto i $c. Spodziewałem się ciebie.$B$BMam kilka zadań, do których szczególnie się nadajesz.', 0),
(10072, 'koKR', 'Ach, świetnie – oto i $c. Spodziewałem się ciebie.$B$BMam kilka zadań, do których szczególnie się nadajesz.', 0),
(10073, 'koKR', 'Dobra robota, $N. Szybko stajesz się $gjednym z moich najlepszych uczniów:jedną z moich najlepszych uczennic; i z niecierpliwością czekam na dalsze szkolenie.', 0),
(10166, 'koKR', 'Nie należę już do tego świata i muszę uznać swoją porażkę. Ta ziemia zmieniła się na zawsze i nic już nie będzie takie jak dawniej. Zostaw wisior tutaj, przy mnie. Może pewnego dnia, długo po odejściu elfów, w tym właśnie miejscu wyrośnie nowe drzewo – pośród spalonego lasu i łupin martwych drzewców.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(8325, 'koKR', 'Odbudowa naszego społeczeństwa zaczyna się tutaj, $N. Gdy zabezpieczymy nasz dom, będziemy mogli spojrzeć dalej i sięgnąć wyżej.', 0),
(8326, 'koKR', 'Nie sprawia mi przyjemności prosić cię o zabijanie tych zwierząt. Dawniej żyliśmy we względnej harmonii ze stworzeniami lasu, lecz czasy się zmieniły. Pierwszą powinnością każdego sin\'dorei jest przetrwanie – pamiętaj o tym.', 0),
(8330, 'koKR', '$GZnalazłeś:Znalazłaś; już moje rzeczy? Gdy odzyskamy władzę nad Wyspą Słońcobieżców, będą mi potrzebne w pracy. Na razie jednak muszę czuwać nad Słoneczną Studnią... a raczej nad tym, co z niej zostało.', 0),
(8334, 'koKR', 'Lepiej, żebyś teraz, a nie później, $gpoznał:poznała; prawdę o przetrwaniu – i o jego cenie. Jako $gkrwawy elf:krwawa elfka; będziesz $gmusiał:musiała; przywyknąć do trudnych wyborów.$B$BNikt nam nie pomógł, gdy Plaga rozdarła nasz dom na pół. Podnieśliśmy się z upadku sami, wyłącznie o własnych siłach.', 0),
(8335, 'koKR', 'Zważ dobrze na tę przestrogę: Felendren Wygnany to tylko objaw znacznie poważniejszego problemu. Jego śmierć rozwiąże nasze bieżące kłopoty, lecz każdego krwawego elfa może spotkać ten sam los, jeśli pozwolimy, by nałóg wziął nad nami górę.', 0),
(8336, 'koKR', 'Wiele stworzeń na wyspie było niegdyś spętanych naszą magią – uległych i pozbawionych agresji. Gdy Plaga zniszczyła Słoneczną Studnię, nasza władza nad nimi prysła. Tajemne odłamki to pozostałości dawnej kontroli, więc być może da się z nich wykonać nowe urządzenie, które pomoże nam ją odzyskać.$B$BCo więcej, może odłamki pozwolą ustalić, jaka niemoc naprawdę trawi wyspę...', 0),
(8338, 'koKR', 'Sądząc po twojej postawie, sprawa jest pilna. Czy mogę ci w czymś konkretnym pomóc?', 0),
(8345, 'koKR', '$GPrzeczytałeś:Przeczytałaś; już tablicę na kaplicy, $N?', 0),
(8346, 'koKR', 'Ach, $N. $GWykonałeś:Wykonałaś; zadanie?', 0),
(8350, 'koKR', 'Witaj w mojej karczmie, $N. Czy dobrze rozumiem, że masz coś dla mnie?', 0),
(8463, 'koKR', '$GOdzyskałeś:Odzyskałaś; już skradzione dobra?', 0),
(8468, 'koKR', 'Masz mi coś do pokazania?', 0),
(8472, 'koKR', '$GZebrałeś:Zebrałaś; już tajemne rdzenie, $N?', 0),
(8473, 'koKR', 'Lękam się pytać, $N... czy to już zrobione?', 0),
(8474, 'koKR', 'Masz mi coś do pokazania?', 0),
(8475, 'koKR', '$GWróciłeś:Wróciłaś;, $N. $GOdparłeś:Odparłaś; już nieumarłych na Trupiej Bliźnie?', 0),
(8476, 'koKR', 'Tor\'Watha i Zeb\'Watha znajdziesz na południowy wschód stąd. Wróć, gdy wybijesz trolle.', 0),
(8477, 'koKR', '$GPrzyniosłeś:Przyniosłaś; mi młot Otembego?', 0),
(8479, 'koKR', 'Ty przynieść mi łeb Zul\'Marosha?', 0),
(8480, 'koKR', '$GZebrałeś:Zebrałaś; już utraconą broń?', 0),
(8482, 'koKR', 'Masz coś dla mnie? Pokaż.', 0),
(8483, 'koKR', '$GZałatwiłeś:Załatwiłaś; intruza?', 0),
(8486, 'koKR', '$GRozprawiłeś:Rozprawiłaś; się z tajemnymi upiorami?', 0),
(8487, 'koKR', '$GSkończyłeś:Skończyłaś; już zbierać próbki, o które prosiłam, $N?', 0),
(8490, 'koKR', '$GZdołałeś:Zdołałaś; już zasilić kamień runiczny, $N?', 0),
(8491, 'koKR', '$GWróciłeś:Wróciłaś;. $GPrzyniosłeś:Przyniosłaś; skóry?', 0),
(8547, 'koKR', 'Witaj! Miło cię poznać!$B$BWidzę, że masz specjalny bon. Oddaj mi go, a dam ci coś w zamian.', 0),
(8884, 'koKR', 'My, tropiciele z Ustronia Obieżyświatów, poświęciliśmy się naprawie szkód wyrządzonych naszym pięknym ziemiom. Nie cofniemy się przed niczym, by tego dokonać.$B$BUfam, że $gwróciłeś:wróciłaś; z łbami murloków, o które cię prosiłem?', 0),
(8885, 'koKR', 'Jesteś narzędziem mojego sukcesu i mojej zemsty!$B$BCzy masz pierścień?', 0),
(8886, 'koKR', 'Jestem wdzięczna za pomoc kogoś takiego jak ty, $N. Niemal wywołuje to uśmiech na mojej twarzy. Ale potem przypominam sobie, co te potwory zrobiły z moim statkiem i co się dzieje z Quel\'Thalas.$B$BUdało ci się odzyskać choć część mojego ładunku?', 0),
(8887, 'koKR', 'Witaj, $N, jakże miło cię widzieć. Wiem, to szaleństwo, że tu siedzę, skoro Nędzni opanowali przystań. Velendris i jego tropiciele przysięgli mnie chronić pod warunkiem, że wyniosę się stąd, gdy tylko odzyskam ładunek.$B$BCo tam masz... wygląda jakoś znajomo?', 0),
(8889, 'koKR', 'Z tej odległości nie mam pewności... czy już $godciąłeś:odcięłaś; zasilanie Iglicy Krańca Mroku?', 0),
(8891, 'koKR', 'Co to? Wygląda znajomo. O nie, ten dziennik... moje badania... to od tego wszystko się zaczęło.', 0),
(8892, 'koKR', '$GDałeś:Dałaś; tym Nędznym nauczkę?', 0),
(8894, 'koKR', 'No i jak, $gzałatwiłeś:załatwiłaś; sprawę? $GRozprawiłeś:Rozprawiłaś; się z porządną liczbą tych magicznych anomalii? Co ja pocznę, jeśli magister Kraniec Mroku wróci, a tu wszędzie będzie się to plątać?', 0),
(9062, 'koKR', 'Bez powodzenia? Cóż, szukaj dalej. Ta księga jest niezwykle ważna, $N.', 0),
(9064, 'koKR', 'Cóż takiego sprawia, że przerywasz mi wykład, $N?', 0),
(9066, 'koKR', '$GZrobiłeś:Zrobiłaś; to, o co prosiłem, $N?', 0),
(9067, 'koKR', 'Czyż nie posłałem cię właśnie po więcej zapasów na przyjęcie? Czy to $gbyłeś:byłaś; ty? Och, nie można ode mnie oczekiwać, że zapamiętam każdą twarz, prawda? Poznaję tylu... interesujących ludzi.$B$BCzego sobie życzysz?', 0),
(9076, 'koKR', 'No więc, masz jego głowę czy nie? Nie mam czasu do stracenia, $N.', 0),
(9147, 'koKR', 'No i? $GPrzyniosłeś:Przyniosłaś; to, czego potrzebuję? Pośpiesz się, bo ten śliczny elfi chłopiec wyzionie ducha!', 0),
(9148, 'koKR', 'Masz list?', 0),
(9252, 'koKR', 'Zwyciężymy, $N.', 0),
(9352, 'koKR', '$GOdkryłeś:Odkryłaś; coś? Czy stoją za tym nocne elfy?', 0),
(9360, 'koKR', 'Co chcesz mi pokazać?', 0),
(9402, 'koKR', 'Jak woda?', 0),
(9403, 'koKR', 'Tylko woda z Wodospadów Elrendar jest dość czysta, by używać jej w magii. Masz ją?', 0),
(9404, 'koKR', 'Masz żywą gałąź? Oddaj ją, szybko!', 0),
(9484, 'koKR', 'Czy $gzapanowałeś:zapanowałaś; już nad smoczym jastrzębiem?', 0),
(9485, 'koKR', 'Czy $gzapanowałeś:zapanowałaś; już nad mglistym nietoperzem?', 0),
(9486, 'koKR', 'Czy $gpolowałeś:polowałaś; już u boku skoczołapa?', 0),
