INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2823, 'koKR', '„Tysiące lat temu wygnani Wysoko Urodzeni przybili do brzegów Lordaeronu i założyli zaczarowane królestwo Quel\'Thalas. Te wysokie elfy, jak same siebie nazywały, stworzyły w sercu swojej krainy źródło ogromnej magicznej energii – Słoneczną Studnię. Z czasem uzależniły się od jej niestabilnej mocy, mimo gorzkich lekcji, jakie wyniosły z minionych epok.”', 0),
(2824, 'koKR', '„Podczas Trzeciej Wojny nikczemny książę Arthas najechał Quel\'Thalas i obrócił niegdyś potężne królestwo w gruzy i popioły. Jego armia nieumarłych wybiła niemal dziewięćdziesiąt procent wysokich elfów. Co więcej, wykorzystał energię Słonecznej Studni, by wskrzesić Kel\'Thuzada – potężnego nieumarłego lisza – i tym samym skaził mistyczne wody Studni. Nieliczne ocalałe elfy, pojąwszy, że zostały odcięte od źródła swojej tajemnej mocy, stawały się coraz bardziej niestabilne i zdesperowane.”', 0),
(2825, 'koKR', '„W najczarniejszej godzinie elfów pojawił się Kael\'thas Słońcobieżca – ostatni potomek królewskiego rodu Quel\'Thalas. Kael, jak go powszechnie nazywano, wiedział, że niedobitki jego ludu nie przetrwają długo bez życiodajnej magii, która niegdyś dodawała im sił. Nazwał swój lud krwawymi elfami na cześć poległych rodaków i nauczył go czerpać z mistycznych energii otoczenia – nawet demonicznych – aby ugasić straszliwe pragnienie magii.”', 0),
(2826, 'koKR', '„W poszukiwaniu nowego przeznaczenia dla swojego ludu – zwanego teraz w elfiej mowie sin\'dorei – Kael\'thas wyruszył do odległego świata Rubieży, gdzie spotkał upadłego nocnego elfa, Illidana. Pod okiem Illidana Kael i jego krwawe elfy odzyskały znaczną część dawnej potęgi.”', 0),
(2827, 'koKR', '„Niestety, skłonność krwawych elfów do sięgania po demoniczne energie sprawiła, że dawni towarzysze z Przymierza zaczęli się od nich odwracać. Dlatego krwawe elfy, które pozostały w Azeroth, z desperacją zwracają się ku Hordzie, licząc, że pomoże im dotrzeć do Rubieży, gdzie będą mogły połączyć się z Kael\'thasem i osiągnąć złote przeznaczenie, które im obiecał.”', 0),
(2846, 'koKR', 'Żarliwie ufam, że dzięki moim badaniom znajdę dodatkowe źródło magicznej energii, bezpieczne dla mojego ludu. Skoro nie ma już Słonecznej Studni, musimy znaleźć sposób, by żyć jak dotąd, nie ulegając pokusie tajemnej magii.$B$BWierzę, że przyszłość sin\'dorei znów może posłużyć wszystkim za świetlany przykład!', 0),
(2847, 'koKR', 'Jak dotąd bez powodzenia. Ta odrobina magii, do której mam swobodny dostęp, musi być przepuszczana przez Iglicę. Mam jednak kilka intrygujących pomysłów. Każę najzdolniejszym uczniom podążyć tymi tropami i zobaczymy, do czego dojdziemy.', 0),
(2848, 'koKR', 'Dawno nic nie pisałem na tych stronach. Wciąż nic obiecującego. Wczoraj dotarła do mnie wieść, że jeden z uczniów na Wyspie Słońcobieżców, niejaki Felendren, zlekceważył rady swoich mentorów i uległ przypadłości.$B$BPodwoję nasze wysiłki.', 0),
(2849, 'koKR', 'Nic. Nie tracę jednak nadziei. Sin\'dorei nie mogą sobie pozwolić na uzależnienie od magii teraz, gdy od południa napiera na nas wróg.$B$BOpracowałem zupełnie nowe podejście; jeśli się powiedzie, pozwoli mi odfiltrować „zanieczyszczenia” z kilku skażonych źródeł spaczonej magii, które trzymam w ukryciu. Muszę postępować ostrożnie.', 0),
(2850, 'koKR', 'Zdumiewające! Odnieśliśmy pewien sukces, choć ilość magii, którą zdołaliśmy wydobyć, była znikoma. Odciągnę większość uczniów od ich studiów, by skupili się na tym obiecującym podejściu.$B$BJeśli dopisze nam choć odrobina szczęścia, zdołamy udoskonalić proces i upiec dwie pieczenie przy jednym ogniu – zyskać obfite źródło energii dla siebie i sposób na odparcie każdej spaczonej magii, na jaką trafimy w przyszłości!', 0),
(2851, 'koKR', 'Nie! Podczas eksperymentów z nowym procesem mój główny uczeń, Telethayon, nagle i bez ostrzeżenia zwiądł na moich oczach, popadając w stan, który trapi moich pobratymców. Próbowałem to powstrzymać, ale zaszedł za daleko. Nie miałem wyboru – musiałem skrócić jego cierpienia.$B$BTaka jest cena odkrycia, lecz już teraz zbyt boleśnie odczuwam jej ciężar.', 0),
(2852, 'koKR', 'To ponad moje siły... dwoje kolejnych uczniów uległo przypadłości. Byliśmy tak ostrożni... Nie rozumiem, co poszło nie tak.$B$BBędę musiał porzucić te badania i zacząć wszystko od nowa.', 0),
(2853, 'koKR', 'Było już za późno. Trzeci z uczniów bez mojej wiedzy dzielił się skażonymi wynikami badań z kilkoma innymi. Spróbuję opanować sytuację, ale najpierw muszę odesłać stąd uczniów, których to nie dotknęło.$B$BZrobię to, oznajmiając wszystkim, że udaję się na urlop naukowy do Ustronia Obieżyświatów w nadziei, że znajdę nowe podejście do problemu.$B$BMuszę znaleźć sposób, by odpokutować ten straszliwy błąd w ocenie.', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(50031, 'koKR', 'Niestety, $N, mam zbyt wiele na głowie, by rozmawiać. Jak wspomniałem, potrzebuję czasu, by przemyśleć obecną sytuację.$B$BŻyczę ci powodzenia w podróży. Bywaj.', 'Niestety, $N, mam zbyt wiele na głowie, by rozmawiać. Jak wspomniałem, potrzebuję czasu, by przemyśleć obecną sytuację.$B$BŻyczę ci powodzenia w podróży. Bywaj.', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
