INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(16147, 0, 4, 'koKR', 'Jestem taka zmęczona. Naprawdę nie powinniśmy byli siedzieć do tak późna zeszłej nocy... no, dzisiejszego ranka. Ale było cudownie! Wydajesz najwspanialsze wieczorki, milordzie.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(10758, 'koKR', '', '$N! Mam nadzieję, że jesteś $ggotów:gotowa; do pracy, bo na Wyspie Słońcobieżców czeka cię mnóstwo zadań.$B$BOd kiedy Arthas i Plaga zniszczyli Słoneczną Studnię, dryfujemy po morzu niepewności. Balansujemy na krawędzi zapomnienia. To się zmieni, $N, a ty będziesz się uczyć i zarazem pomagać nam się podźwignąć.$B$BCzeka na nas Rubież!', 0),
(10763, 'koKR', 'Ze Słonecznej Iglicy roztaczał się piękny widok na Słoneczną Studnię... niegdyś. Nasze życie wywróciło się do góry nogami, $N, lecz mimo to trwamy. Taka już nasza natura – umiemy przetrwać.$B$BJeśli masz przetrwać ten wstrząs... i iść dalej o własnych siłach, MUSISZ się nauczyć, jak przetrwać. Każdy krwawy elf musi to opanować. Musisz zapanować nad swoim nienasyconym głodem magii, zanim on zapanuje nad tobą.', '', 0),
(10765, 'koKR', 'Wiedza to potęga – PRAWDZIWA potęga, $gmój młody przyjacielu:moja młoda przyjaciółko;. Mądrze zrobisz, zdobywając jej jak najwięcej i z należytą uwagą słuchając tych, którzy już to uczynili.$B$BPrzed zburzeniem Słonecznej Studni łudziliśmy się, że nasza cywilizacja zbliża się do szczytu. Dopiero Plaga rzuciła nas na kolana... i poniekąd sprowadziła z powrotem na ziemię.', '', 0),
(10766, 'koKR', 'Zastajesz mnie w przełomowym momencie moich badań! Nic nie szkodzi, możesz przyłączyć się do mnie w cichej kontemplacji... z naciskiem na „cichej”, jeśli łaska.', '', 0),
(10767, 'koKR', '', 'Jeśli wybierasz się do miasta, mam dla ciebie ważne zadanie!', 0),
(10889, 'koKR', '', 'Ach, $N – dobrze cię znów widzieć. Ufam, że twoje sprawy idą pomyślnie.', 0),
(10986, 'koKR', 'Głowa do góry! Twoi przyjaciele nie będą długo opłakiwać twojej śmierci!', '', 0),
(10992, 'koKR', 'Idź dalej, $N!', '', 0),
(10993, 'koKR', 'Odejdź, $N!', '', 0),
(10994, 'koKR', 'Nie przeciągaj struny, $gobywatelu:obywatelko;!', '', 0),
(11000, 'koKR', '$N, dobrze cię znów widzieć.$B$BPamiętaj, by skupiać się na nauce. Jesteś naszą przyszłością, a jeśli się potkniesz, nasze jutro będzie doprawdy mroczne.', '', 0),
(11003, 'koKR', '', 'Witaj w karczmie na Placu Sokolego Skrzydła. Czy mogę przygotować ci posiłek albo pokój?', 0),
(11023, 'koKR', 'Magia to coś więcej niż tajemne gesty... ale mówię do kogoś, kto już o tym wie, prawda?$B$BPrzychodzisz do mnie po naukę i nauczysz się... pod warunkiem, że będziesz uważać i robić, co każę. Tajemnice demonów nie sprzyjają głupcom – ja również nie.', 'Magia to coś więcej niż tajemne gesty... ale mówię do kogoś, kto już o tym wie, prawda?$B$BPrzychodzisz do mnie po naukę i nauczysz się... pod warunkiem, że będziesz uważać i robić, co każę. Tajemnice demonów nie sprzyjają głupcom – ja również nie.', 0),
(11696, 'koKR', 'Długo trudziliśmy się, by przywrócić naszej ziemi dawną świetność, $N. Zawsze będziemy czujni wobec tych, którzy najechali i splugawili Quel\'Thalas. Nie spoczniemy, dopóki nie znikną nam z oczu.$B$BNiech nie ostanie się nikt, kto stanie na drodze sin\'dorei!', '', 0),
(11697, 'koKR', '', 'Wszystko przepadło, $N, i to wyłącznie moja wina! Ostrzegano mnie, żebym wypłynęła z portu, póki był czas, ale czy posłuchałam? Nie.$B$BCo ja teraz pocznę? Ci chorowici krwawi elfowie, Nędzni, ukradli moje magiczne towary i chyba je zjedli. Jestem prawie pewna, że to znaczy, że już ich nie odzyskam. A murloki Ponurej Łuski pod osłoną nocy złupiły resztę mojego ładunku! Na domiar złego, jakby mało było kopania leżącej uczciwej kupczyni, moja załoga opuściła statek!$B$BChyba się rozpłaczę.', 0),
(11698, 'koKR', '', 'Witaj, $N. Nastały doprawdy niespokojne czasy, jeśli taki los czeka nasze ukochane Quel\'Thalas.', 0),
(11701, 'koKR', 'Nędzni są dla mnie jak sól w oku, $N. Kiedy akurat nie narażają samych siebie, czerpiąc z niestabilnych źródeł tajemnej mocy, by zaspokoić swój głód, knują niedorzeczne intrygi przeciw naszemu szacownemu społeczeństwu.', '', 0),
(11713, 'koKR', 'I bardzo dobrze... teraz nikt już nie powtórzy moich błędów!', '', 0),
(11714, 'koKR', 'Mam nadzieję, że z Loralthalis wszystko w porządku, $N. Może powinienem sam udać się do Iglicy Krańca Mroku? Może powinienem był zrobić to od razu?', '', 0),
(11716, 'koKR', 'Bałagan, oto co tu mamy! Wszystkie te stworzenia wyrosły nie wiadomo skąd i szaleją bez żadnej kontroli! I gdzie się podziali magister i jego uczniowie? Zostawili mnie tu samego, nawet nie rzucając: „Hej, Wyllithenie, może pójdziesz z nami?”.$B$BCo za tupet!', '', 0),
(11717, 'koKR', 'Te wasze tajemne sanktuaria są doprawdy... interesujące, panie Caidanis. Dziękuję za informacje, które mi pan dziś przekazał.', '', 0),
(11718, 'koKR', 'Cała przyjemność po mojej stronie, panie Kowadłostrożu. Muszę przyznać, że pańskie gorliwe zainteresowanie naszą działalnością jest nader... nieoczekiwane.', '', 0),
(11730, 'koKR', 'Na co się gapisz, $gchłopcze:dziewczyno;? Krasnoluda nigdy nie $gwidziałeś:widziałaś; czy co?$B$BLepiej idź w swoją stronę, jeśli nie szukasz kłopotów.', '', 0),
(11731, 'koKR', 'Proszę o chwilę rozmowy, panie.', 'Proszę o chwilę rozmowy, panie.', 0),
(11732, 'koKR', 'Ach, to pewnie ty masz mnie oprowadzić po Gaju Wszechpieśni, $gchłopcze:dziewczyno;. Nie spieszyło ci się, co?$B$BNo dobrze, ruszajmy. Nie traćmy ani minuty dłużej.', '', 0),
(11733, 'koKR', 'Ależ... tak, oczywiście. Chcę panu coś pokazać, tuż w tym budynku, panie Kowadłostrożu.', 'Ależ... tak, oczywiście. Chcę panu coś pokazać, tuż w tym budynku, panie Kowadłostrożu.', 0),
(11734, 'koKR', 'Dobrze więc. Zobaczmy, co masz mi do pokazania, $N.', '', 0),
(11735, 'koKR', 'Co to za sztuczki? Jeśli chcesz zastawić na mnie zasadzkę, ostrzegam, że nie padnę bez walki!', '', 0),
(11988, 'koKR', 'Och, witaj... hm, jak ci na imię?$B$BMniejsza z tym. Co cię sprowadza do mojego drugiego domu, tu, pośród pięknej prowincji?', '', 0),
(11992, 'koKR', '', 'Milordzie, czy możemy wkrótce dołączyć do przyjęcia? Tak się tu nudzę.', 0),
(11993, 'koKR', '', 'Och, milordzie, tak bardzo liczę, że zamówiłeś więcej tego wybornego wina ze Srebrnej Luny. Śmiem twierdzić, że po nim czuję się niemal tak swobodnie jak pierwsza lepsza prostaczka!', 0),
(11995, 'koKR', '', 'Lordzie Saltherilu, mój drogi, czy zauważyłeś, że zapasy na przyjęcie nieco się kurczą? Naprawdę powinniśmy posłać po jednego z tych kurierów z Wioski Rześkiej Bryzy, żeby dowiózł wszystkiego, czego trzeba. Szczególnie lubię te maleńkie przekąski zawijane w wędzony boczek. Jak one się nazywają?', 0),
(11996, 'koKR', 'Jak sobie życzysz, moja droga, jak sobie życzysz.', '', 0),
(11997, 'koKR', 'Hm, co mówiłaś? Wybacz, moja droga, chyba bujałem w obłokach.', '', 0),
(11998, 'koKR', 'Och, jak najbardziej, Elisaro. Ale czy mogłabyś, proszę, okazać choć odrobinę cierpliwości?', '', 0),
(11999, 'koKR', 'Czyżby? Jakież to interesujące. Moja droga, może pójdziesz przypudrować nosek? Mam wiele do przemyślenia.', '', 0),
(12001, 'koKR', '', 'Witaj, $gmój panie:moja pani;. Ufam, że miło spędzasz czas?', 0),
(12013, 'koKR', 'Co? Och, tylko nie to znowu!', '', 0),
(12014, 'koKR', 'Nie możesz mi tego zrobić! Mieliśmy umowę!', '', 0),
(12060, 'koKR', 'Jesteśmy zbyt łaskawi dla Nędznych. Powinniśmy przebić mieczem każdego z nich.$B$BIch zuchwałość w Przystani Słonecznego Żagla jest niewybaczalna.', '', 0),
(12061, 'koKR', '', 'Za mną długi dzień wycinania bezmyślnej Plagi, która bez końca maszeruje Trupią Blizną. Mam nadzieję, że $gprzyszedłeś:przyszłaś; pomóc, a nie marnować mój czas czczą paplaniną.', 0),
(12070, 'koKR', '', 'Tak sobie myślałam... naprawdę powinniśmy któregoś wieczoru wybrać się na południe, może urządzić piknik z widokiem na walki na granicy? Co o tym myślisz, milordzie? Czy to nie byłoby ekscytujące?', 0),
(12071, 'koKR', '', 'Milordzie, skoro tylu szlachetnie urodzonych sin\'dorei niestety padło, czy to znaczy, że wkrótce możesz liczyć na wyniesienie? Tak się cieszę twoim szczęściem!', 0),
(12092, 'koKR', '$N, spójrz, co zrobili z naszą ukochaną ziemią. Plaga musi zostać zniszczona!', '', 0),
(12093, 'koKR', '', 'Trochę to potrwa, ale chyba zdołamy ocalić życie temu krwawemu elfowi.', 0),
(12094, 'koKR', 'Kim jesteś? Jest mi... tak... zimno.', '', 0),
(12095, 'koKR', '', 'To hańba, że my, sin\'dorei, utraciliśmy tak wiele z tego, co niegdyś zwaliśmy domem. Już niedługo odzyskamy siły i wydrzemy Pladze nasze południowe ziemie!', 0),
(12149, 'koKR', 'Ten ból... ten głód... pragnę więcej...', 'Ten ból... ten głód... pragnę więcej...', 0),
(12150, 'koKR', 'Więcej, więcej, więcej! Muszę się wkrótce pożywić.', 'Więcej, więcej, więcej! Muszę się wkrótce pożywić.', 0),
(12151, 'koKR', 'Nie zniosę tego bólu. Muszę znaleźć nowe źródło.', 'Nie zniosę tego bólu. Muszę znaleźć nowe źródło.', 0),
(12186, 'koKR', 'Zanim pokonamy wrogów z zewnątrz, takich jak Plaga i trolle Amanów, musimy przezwyciężyć przeszkody we własnych szeregach. Nędzni dość już się nam naprzykrzali; czas się z nimi rozprawić.', '', 0),
(12230, 'koKR', 'Arkanisto Vandril, co tu robią Porzuceni?', 'Arkanisto Vandril, co tu robią Porzuceni?', 0),
(12233, 'koKR', 'Sytuacja jest poważniejsza, niż wielu się wydaje. Porzuceni są tu jako sojusznicy w walce z naszym wspólnym wrogiem, Plagą.$B$BWierz mi, gdyby nie oni, Widmowe Ziemie byłyby stracone, a Plaga dawno zalałaby cały Gaj Wszechpieśni!$B$BPonad wszystko jednak potrzebujemy twojej pomocy w odzyskaniu naszych niegdyś dumnych ziem!', '', 0),
(12244, 'koKR', 'Te kamienie runiczne chronią ziemie Gaju Wszechpieśni przed skażeniem Plagi. Zachodni Kamień Runiczny zawiódł dawno temu i musieliśmy wypalić ziemię wokół niego.$B$BDopóki żyję, nie pozwolę, by zawiodły pozostałe kamienie. Oto moja przysięga.', '', 0),
(12272, 'koKR', '%s oddaje resztki swojej energii pobliskiemu kamieniowi runicznemu i przywraca mu moc.', '', 0),
(12339, 'koKR', 'Nasze sanktuaria czerpią tajemną energię z prądów linii mocy, które płyną przez nasze ziemie, niewidoczne gołym okiem.$B$BGdy zabrakło Słonecznej Studni, zapewniają nam stałe i pewne źródło siły.', '', 0),
(12340, 'koKR', 'To, że Wioska Rześkiej Bryzy wciąż stoi, świadczy o nieustępliwości naszej rasy. Nigdy więcej nie uznamy się za pokonanych przez Plagę.', '', 0),
(12400, 'koKR', '', 'Jeśli masz pieniądze, ja mam jedzenie i napoje, które zaspokoją twój apetyt. Każdy miedziak idzie na utrzymanie Ustronia w nienagannym stanie.', 0),
(12404, 'koKR', 'Mam na sprzedaż wszelkiego rodzaju towary, $N. Oglądaj bez pośpiechu.', '', 0),
(12406, 'koKR', '', 'Czy tym nieumarłym nie ma końca? Zdaje się, że na miejsce każdego zabitego ghula czy szkieletu pojawiają się dwa nowe.', 0),
(12417, 'koKR', '', 'Ognia!', 0),
(12418, 'koKR', '', 'Wróg w zasięgu wzroku! Broń w pogotowiu!', 0),
(12419, 'koKR', '', 'Utrzymać pozycje!', 0),
(12437, 'koKR', '', 'Co cię tu sprowadza, $N? Niewielu tu zagląda. I chyba nie bez powodu.', 0),
(12438, 'koKR', '', 'Chcesz nauczyć się kowalstwa, czy masz mi do powiedzenia coś innego?', 0),
(12726, 'koKR', 'Gdzie... gdzie ja jestem?', '', 0),
(12728, 'koKR', '', 'Nigdzie się jeszcze nie wybierasz, przystojniaku. Nie, dopóki nie odzyskasz sił.', 0),
(12780, 'koKR', '%s pęka, zasypując okolicę tajemnym osadem!', '', 0),
(12786, 'koKR', 'Czy ktoś potrzebuje zaopatrzenia na polowanie na trolle? Każdy troll się nada.', '', 0),
(12787, 'koKR', 'Czemu sprzymierzamy się z plugawymi, cuchnącymi trollami? Dobry troll to martwy troll.', '', 0),
(12788, 'koKR', 'Czym mogę służyć?', 'Czym mogę służyć?', 0),
(12789, 'koKR', 'Precz, plugawa kreaturo! Nie pojmuję, jak ktokolwiek może znosić twój brud.', '', 0),
(12790, 'koKR', 'Mogę obejrzeć twoje towary?', 'Mogę obejrzeć twoje towary?', 0),
(12793, 'koKR', '', 'Smocze jastrzębie, jeśli są dobrze wychowane, bywają naprawdę łagodne. Czy to nie fascynujące? Tak przyjazne i towarzyskie, gdy się je dobrze wychowa, a tak zajadłe i zabójcze na wolności... Po prostu je uwielbiam.', 0),
(12796, 'koKR', '', 'Naprawdę nie sądzę, żeby nasze położenie było aż tak złe. Jestem pewna, że wszystko wkrótce się ułoży, a moc Słonecznej Studni zostanie przywrócona. Nie może być aż tak źle, jak wszyscy mówią.', 0),
(12833, 'koKR', 'Gadaj! Gdzie ukrywa się twój przywódca?', '', 0),
(12834, 'koKR', 'Nic nie dostaniesz, dopóki nie zaczniesz mówić, szumowino!', '', 0),
(12840, 'koKR', 'Myślisz, że jestem okrutny dla tego robaka?$B$BW tym miesiącu zabili dwóch moich ludzi! Jesteśmy zbyt łagodni wobec tej hołoty, Nędznych.', '', 0),
(12842, 'koKR', '', 'Witaj w Wiosce Rześkiej Bryzy. Srebrna Luna niemal o nas zapomniała, ale nie zamierzamy odejść. To nasz dom.', 0),
(12847, 'koKR', '', 'Moja praca polega na jednym i tylko jednym zadaniu: dopilnować, by Zachodnie Sanktuarium działało bez zakłóceń.$B$BWybacz mi rozdrażnienie, ale, jak widzisz, sytuacja nieco wymknęła się tu spod kontroli.', 0),
(12861, 'koKR', '', 'Zabijcie ich! Nie pozwólcie, by to ścierwo z Plagi zbezcześciło nasze miasto!', 0),
(13158, 'koKR', '', 'Czy to sprawka sabotażystów z nocnych elfów? Wątpię. Przy obciążeniu, jakim obarczaliśmy Zachodnie Sanktuarium, awaria była tylko kwestią czasu.', 0),
(13339, 'koKR', 'Och... czy my się znamy?', 'Och... czy my się znamy?', 0),
(13340, 'koKR', 'Witaj, $N! Dobrze się bawisz?', 'Witaj, $N! Dobrze się bawisz?', 0),
(13341, 'koKR', 'Hej, wszyscy, to $N!', 'Hej, wszyscy, to $N!', 0),
(13342, 'koKR', 'W tym towarzystwie wieści szybko się rozchodzą. Dzięki za uzupełnienie zapasów!', 'W tym towarzystwie wieści szybko się rozchodzą. Dzięki za uzupełnienie zapasów!', 0),
(13343, 'koKR', 'To przyjęcie jest po prostu najlepsze! Nie uważasz?', 'To przyjęcie jest po prostu najlepsze! Nie uważasz?', 0),
(13344, 'koKR', 'Musisz spróbować przystawek ze skoczołapa, są po prostu boskie!', 'Musisz spróbować przystawek ze skoczołapa, są po prostu boskie!', 0),
(13345, 'koKR', 'Hmm... chyba tegoroczna specjalna rezerwa muśnięta słońcem wcale nie jest taka specjalna. Nie sądzisz, $N?', 'Hmm... chyba tegoroczna specjalna rezerwa muśnięta słońcem wcale nie jest taka specjalna. Nie sądzisz, $N?', 0),
(13346, 'koKR', 'Chodzą słuchy, że dziś wieczorem wszyscy idziemy popatrzeć na bitwę z Plagą na granicy. Cóż za rozkosznie niegodziwy pomysł!', 'Chodzą słuchy, że dziś wieczorem wszyscy idziemy popatrzeć na bitwę z Plagą na granicy. Cóż za rozkosznie niegodziwy pomysł!', 0),
(13347, 'koKR', 'Wyobrażasz sobie, jaki tupet ma ta Elisara Słońcobij? Myśli, że wpadnie w oko lordowi Saltherilowi? A ta jej kreacja? Taka zeszłosezonowa. Doprawdy, to smutne.', 'Wyobrażasz sobie, jaki tupet ma ta Elisara Słońcobij? Myśli, że wpadnie w oko lordowi Saltherilowi? A ta jej kreacja? Taka zeszłosezonowa. Doprawdy, to smutne.', 0),
(13348, 'koKR', 'Wybacz, nie rozmawiam ze służbą.', 'Wybacz, nie rozmawiam ze służbą.', 0),
(13349, 'koKR', 'A kimże ty jesteś?', 'A kimże ty jesteś?', 0),
(13350, 'koKR', 'Obawiam się, że bierzesz mnie za kogoś, kto chce z tobą rozmawiać.', 'Obawiam się, że bierzesz mnie za kogoś, kto chce z tobą rozmawiać.', 0),
(13355, 'koKR', '', 'Saltusiu, nie sądzisz, że wpuszczamy na przyjęcie zbyt wielu „niepożądanych”? Martwię się, co pomyślą o tym nasi przyjaciele.', 0),
(13356, 'koKR', '', 'Obiecałeś, że zabierzesz mnie wieczorem na miasto! Znowu będziemy tu tylko sterczeć przez całą noc?', 0),
(13397, 'koKR', '', 'Cóż za... mroczna... energia! Jak to możliwe?', 0),
(14017, 'koKR', 'Chcę dowiedzieć się więcej o kowalstwie.', 'Chcę dowiedzieć się więcej o kowalstwie.', 0),
(14378, 'koKR', 'Uczniowie są trochę jak owce. Są pożyteczni, a nawet sympatyczni, gdy się ich prowadzi i uważnie pilnuje.$B$BZostaw ich samych na chwilę, a spadną z urwiska albo utopią się w płytkiej rzece.', '', 0),
(14594, 'koKR', 'Nie marnuj mojego czasu. Czego chcesz?', 'Nie marnuj mojego czasu. Czego chcesz?', 0),
(15220, 'koKR', 'Mistrz smoczych jastrzębi', 'Mistrz smoczych jastrzębi', 0),
(15235, 'koKR', 'Jaką ścieżką pragniesz podążać?', 'Jaką ścieżką pragniesz podążać?', 0),
(15251, 'koKR', 'Której profesji pragniesz się nauczyć?', 'Której profesji pragniesz się nauczyć?', 0),
(16035, 'koKR', 'Czy nie widzisz, że mam tu mnóstwo pracy?', 'Czy nie widzisz, że mam tu mnóstwo pracy?', 0),
(16036, 'koKR', 'Tak? Czego chcesz?', 'Tak? Czego chcesz?', 0),
(16037, 'koKR', 'A ty jesteś...?', 'A ty jesteś...?', 0),
(16039, 'koKR', 'Moja siostra Silanna naiwnie nie dostrzega rosnącego zagrożenia w tych lasach. Ale czy jej się to podoba, czy nie, gdy tylko załaduję ten wóz, przenosimy się za mury miasta. $b$bWygląda na to, że mam tu więcej toreb, niż potrzebuję. Może tobie się przydadzą.\n', '', 0),
(16099, 'koKR', 'A niech to! Za każdym razem, gdy coś załaduję na wóz, po chwili znów się tu pojawia!\n', 'A niech to! Za każdym razem, gdy coś załaduję na wóz, po chwili znów się tu pojawia!\n', 0),
(16100, 'koKR', 'Mogłem się domyślić, że nie należy dawać Silannie tej księgi magicznych sztuczek.\n', 'Mogłem się domyślić, że nie należy dawać Silannie tej księgi magicznych sztuczek.\n', 0),
(16773, 'koKR', 'Mało ci jeszcze krzywd? Musisz też zakłócać mój sen?', '', 0),
(16774, 'koKR', 'Czemu ma służyć ta przemoc? Co się stało, to się nie odstanie. Mój lud zawiódł się na mnie.', '', 0),
(17595, 'koKR', '%s budzi się przestraszony.', '', 0),
(17596, 'koKR', 'Czy... czy to wszystko był sen? Lazurowa Mgła, Krwawa Mgła, Moczary Zangarskie, Cienisty Księżyc... nawet Zul\'Aman... Jane! Jane, gdzie jesteś?!', '', 0),
(17597, 'koKR', 'Ach, cudownie. To był tylko sen...', '', 0),
(17598, 'koKR', '', 'Jestem tutaj, tatusiu. Spałeś cały dzień. Musisz być strasznie zmęczony!', 0),
(17599, 'koKR', '', '%s wraca do zabawy na plaży.', 0),
(17907, 'koKR', '', 'Szybkobieżce to szlachetne stworzenia. Zawsze dobrze traktuj swojego; niewiele rzeczy jest groźniejszych niż rozgniewany szybkobieżca.', 0),
(17918, 'koKR', '', 'Chyba widzę stąd Słoneczną Studnię!', 0),
(17919, 'koKR', '', 'Czy w takiej muszelce naprawdę słychać szum morza?', 0),
(17920, 'koKR', '', 'Oooch! Patrz, jaka błyszcząca!', 0),
(17921, 'koKR', '', 'Ta na pewno spodoba się Jane!', 0),
(17922, 'koKR', '', '%s podnosi muszlę.', 0),
(17923, 'koKR', '', '%s przykłada muszlę do ucha.', 0),
(17924, 'koKR', '', '%s wytrząsa piasek z muszli.', 0),
(18549, 'koKR', 'Szukasz czegoś w naszej pięknej krainie?', 'Szukasz czegoś w naszej pięknej krainie?', 0),
(18550, 'koKR', 'Mistrzyni lotów Zmierzch stoi tuż przed Bramą Magistrów, pod samą Srebrną Luną, i doogląda smoczych jastrzębi.', 'Mistrzyni lotów Zmierzch stoi tuż przed Bramą Magistrów, pod samą Srebrną Luną, i doogląda smoczych jastrzębi.', 0),
(18551, 'koKR', 'Jeśli chcesz zarejestrować gildię, radzę popytać w murach samej Srebrnej Luny.', 'Jeśli chcesz zarejestrować gildię, radzę popytać w murach samej Srebrnej Luny.', 0),
(18552, 'koKR', 'Delaniel prowadzi swoją karczmę w południowo-wschodnim rogu Placu Sokolego Skrzydła. Dobre jedzenie, przednie wino, miękkie łoża... czegóż więcej można pragnąć?', 'Delaniel prowadzi swoją karczmę w południowo-wschodnim rogu Placu Sokolego Skrzydła. Dobre jedzenie, przednie wino, miękkie łoża... czegóż więcej można pragnąć?', 0),
(18553, 'koKR', 'Niektórzy tropiciele najwyraźniej nie potrafią sami zajmować się swoimi zwierzęcymi podopiecznymi. Jeśli koniecznie musisz gdzieś w mieście przechować takie stworzenie, Anathos przejmie je od ciebie. Czeka i pracuje na Placu Sokolego Skrzydła, przed karczmą.', 'Niektórzy tropiciele najwyraźniej nie potrafią sami zajmować się swoimi zwierzęcymi podopiecznymi. Jeśli koniecznie musisz gdzieś w mieście przechować takie stworzenie, Anathos przejmie je od ciebie. Czeka i pracuje na Placu Sokolego Skrzydła, przed karczmą.', 0),
(18554, 'koKR', 'Pewna krowia niewiasta, która podaje się za druidkę, rozbiła obóz w Srebrnej Lunie. Bez wątpienia właśnie w tej chwili pasie się w naszych kwietnikach.', 'Pewna krowia niewiasta, która podaje się za druidkę, rozbiła obóz w Srebrnej Lunie. Bez wątpienia właśnie w tej chwili pasie się w naszych kwietnikach.', 0),
(18555, 'koKR', 'Tropiciele pobierają nauki u Hannovii z Obieżyświatów, która przebywa w północno-wschodnim budynku na Placu Sokolego Skrzydła.', 'Tropiciele pobierają nauki u Hannovii z Obieżyświatów, która przebywa w północno-wschodnim budynku na Placu Sokolego Skrzydła.', 0),
(18556, 'koKR', 'Garridel naucza sztuk tajemnych na Placu Sokolego Skrzydła; znajdziesz ją na piętrze karczmy.', 'Garridel naucza sztuk tajemnych na Placu Sokolego Skrzydła; znajdziesz ją na piętrze karczmy.', 0),
(18563, 'koKR', 'Krwawy Rycerz Noellene czeka na młodych adeptów w północno-wschodnim budynku na placu.', 'Krwawy Rycerz Noellene czeka na młodych adeptów w północno-wschodnim budynku na placu.', 0),
(18564, 'koKR', 'Jeśli szukasz wiedzy kapłańskiej, Ponaris jest tym, kogo potrzebujesz. Pracuje z pozostałymi na piętrze karczmy Delaniel.', 'Jeśli szukasz wiedzy kapłańskiej, Ponaris jest tym, kogo potrzebujesz. Pracuje z pozostałymi na piętrze karczmy Delaniel.', 0),
(18565, 'koKR', 'W północno-wschodniej części Placu Sokolego Skrzydła stoi budynek... w środku najpewniej znajdziesz Tannarię, kobietę niezwykle biegłą w pozostawaniu w ukryciu.', 'W północno-wschodniej części Placu Sokolego Skrzydła stoi budynek... w środku najpewniej znajdziesz Tannarię, kobietę niezwykle biegłą w pozostawaniu w ukryciu.', 0),
(18569, 'koKR', 'Celoenus to nasz miejscowy znawca przyzywania demonów. Przebywa w karczmie na Placu Sokolego Skrzydła, zapewne na piętrze.', 'Celoenus to nasz miejscowy znawca przyzywania demonów. Przebywa w karczmie na Placu Sokolego Skrzydła, zapewne na piętrze.', 0),
(18570, 'koKR', 'Znam pewnego miejscowego alchemika. Sheynathren, jeśli dobrze pamiętam. Gdy ostatnio go widziałem, zmierzał do Azylu Saltherila, bez wątpienia na jedno z tych jego niedorzecznych przyjęć.', 'Znam pewnego miejscowego alchemika. Sheynathren, jeśli dobrze pamiętam. Gdy ostatnio go widziałem, zmierzał do Azylu Saltherila, bez wątpienia na jedno z tych jego niedorzecznych przyjęć.', 0),
(18571, 'koKR', 'Obieżyświaci mają kowala w swoim Ustroniu, we wschodniej części Gaju Wszechpieśni. Może Arathel zdoła ci pomóc.', 'Obieżyświaci mają kowala w swoim Ustroniu, we wschodniej części Gaju Wszechpieśni. Może Arathel zdoła ci pomóc.', 0),
(18572, 'koKR', 'Delaniel zatrudnia uroczą kucharkę imieniem Quarelestra. Dobrze zrobisz, ucząc się od niej. Rzecz jasna, znajdziesz ją w karczmie na Placu Sokolego Skrzydła.', 'Delaniel zatrudnia uroczą kucharkę imieniem Quarelestra. Dobrze zrobisz, ucząc się od niej. Rzecz jasna, znajdziesz ją w karczmie na Placu Sokolego Skrzydła.', 0),
(18573, 'koKR', 'Jeśli szukasz zaklinaczki Eredanii, zajrzyj na tę małą uroczystość u Saltherila. Zaproszenie dostała kilka dni temu.', 'Jeśli szukasz zaklinaczki Eredanii, zajrzyj na tę małą uroczystość u Saltherila. Zaproszenie dostała kilka dni temu.', 0),
(18574, 'koKR', 'Tak niebezpiecznej i nieprzewidywalnej profesji nie sposób uprawiać pośród naszych nieskalanych lasów bez opłakanych skutków. Możesz jednak spróbować w samej Srebrnej Lunie; jej mury są dość mocne, by wytrzymać wybuchy.', 'Tak niebezpiecznej i nieprzewidywalnej profesji nie sposób uprawiać pośród naszych nieskalanych lasów bez opłakanych skutków. Możesz jednak spróbować w samej Srebrnej Lunie; jej mury są dość mocne, by wytrzymać wybuchy.', 0),
(18575, 'koKR', 'Dla tych, którzy wolą polegać na przyziemnych metodach leczenia ran, Kanaria prowadzi schludny punkt w karczmie na Placu Sokolego Skrzydła.', 'Dla tych, którzy wolą polegać na przyziemnych metodach leczenia ran, Kanaria prowadzi schludny punkt w karczmie na Placu Sokolego Skrzydła.', 0),
(18576, 'koKR', 'W naszym wspaniałym mieście jest pewien rybak... jeśli spędzanie czasu z cuchnącymi, mokrymi, trzepoczącymi się paskudztwami to twój pomysł na miły dzień.', 'W naszym wspaniałym mieście jest pewien rybak... jeśli spędzanie czasu z cuchnącymi, mokrymi, trzepoczącymi się paskudztwami to twój pomysł na miły dzień.', 0),
(18577, 'koKR', 'Któż lepiej zadba o kwiatowe dekoracje na przyjęcie niż botanik Tyniarrel? Jestem pewien, że Saltheril płaci mu winem.', 'Któż lepiej zadba o kwiatowe dekoracje na przyjęcie niż botanik Tyniarrel? Jestem pewien, że Saltheril płaci mu winem.', 0),
(18580, 'koKR', 'Naszą miejscową jubilerkę, Aleinię, znajdziesz w lokalu Delaniel na Placu Sokolego Skrzydła. Być może szuka ucznia.', 'Naszą miejscową jubilerkę, Aleinię, znajdziesz w lokalu Delaniel na Placu Sokolego Skrzydła. Być może szuka ucznia.', 0),
(18581, 'koKR', 'Sathein uważa, że skóry rysiów z Gaju Wszechpieśni idealnie nadają się do jego wyrobów. Porozmawiaj z nim – stoi z Mathreynem tuż na południowy zachód od Bramy Magistrów.', 'Sathein uważa, że skóry rysiów z Gaju Wszechpieśni idealnie nadają się do jego wyrobów. Porozmawiaj z nim – stoi z Mathreynem tuż na południowy zachód od Bramy Magistrów.', 0),
(18582, 'koKR', 'Górników znajdziesz w Srebrnej Lunie, zapewne blisko cuchnących kuźni, w których przetapiają swój urobek.', 'Górników znajdziesz w Srebrnej Lunie, zapewne blisko cuchnących kuźni, w których przetapiają swój urobek.', 0),
(18583, 'koKR', 'Mathreyn jest biegły w barbarzyńskiej sztuce skórowania, jeśli naprawdę tego pragniesz. Dostarcza Satheinowi skór; obu znajdziesz tuż na południowy zachód od Bramy Magistrów.', 'Mathreyn jest biegły w barbarzyńskiej sztuce skórowania, jeśli naprawdę tego pragniesz. Dostarcza Satheinowi skór; obu znajdziesz tuż na południowy zachód od Bramy Magistrów.', 0),
(18584, 'koKR', 'Zacna szwaczka jest ostatnio zajęta w Azylu Saltherila; jej biegłość w posługiwaniu się igłą i nicią jest tam z pewnością doceniana.', 'Zacna szwaczka jest ostatnio zajęta w Azylu Saltherila; jej biegłość w posługiwaniu się igłą i nicią jest tam z pewnością doceniana.', 0),
(18726, 'koKR', 'Pokaż mi pisklęta, które masz na sprzedaż.', 'Pokaż mi pisklęta, które masz na sprzedaż.', 0),
(18925, 'koKR', '', 'Nie kupisz tu żadnego szybkobieżcy, dopóki nie dowiedziesz swojej wartości i oddania naszemu ludowi.$b\nNie wracaj, dopóki krwawe elfy nie uznają cię za $gwywyższonego:wywyższoną;. Precz!', 0),
